export class App {
    constructor() {
        this.globalState = GlobalStateManager.getInstance();
        this.tables = {};
        this.tableConfigs = [];
        this.peopleData = [];
        this.uiManager = new UIManager(this);
        this.tableElements = {};
        // Track newly created games in session to prevent 'Deleted' status
