        const ui = new BlackjackUI(game, () => overlay.remove());
        const overlay = ui.render();
        document.body.appendChild(overlay);
    }
}

import '../styles/Table.css';
import '../styles/FilterBar.css';
import { GlobalStateManager } from './GlobalStateManager.js';
import { FilterEngine } from '../utils/FilterEngine.js';
import { Dialog } from '../ui/Dialog.js';

import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { FilterBar } from '../ui/FilterBar.js';

/**
 * TableRenderer - Handles rendering and updating the table UI
 */
export class TableRenderer {
    constructor(table) {
        this.table = table;
        this.element = null;
        this.selectedRows = new Set();
        this.filterBar = null;
    }

    render() {
        this.element = document.createElement('div');
        this.element.className = 'table-wrapper';

        this.element.appendChild(this._renderHeader());

        // Local Filter Bar
        this.filterBar = new FilterBar({
            schema: this.table.schema,
            state: this.table.localFilters,
            tableId: this.table.id,
            onUpdate: () => this.update()
        });

        this.element.appendChild(this.filterBar.render());

        // Context menu on the filter bar itself
        this.filterBar.element.addEventListener('contextmenu', (e) => {
            e.preventDefault();
            e.stopPropagation();
            this._showTableContextMenu(e);
        });

        this.element.appendChild(this._renderTableScroll());

        this.bulkBar = this._renderBulkActionsBar();
        this.element.appendChild(this.bulkBar);

        // Auto-collapse if empty
        if (this.table.rows.length === 0) {
            this.element.classList.add('collapsed');
        }

        return this.element;
    }


    update() {
        if (!this.element) return;
        this.updateMeta();

        const oldBody = this.element.querySelector('tbody');
        if (oldBody) {
            const newBody = this._renderTableBody();
            oldBody.replaceWith(newBody);
        }
    }

    _renderHeader() {
        const header = document.createElement('div');
        header.className = 'table-top';
        header.style.cursor = 'pointer';
        header.title = 'Klicken zum Ein-/Ausklappen';

        const titleGroup = document.createElement('div');
        titleGroup.className = 'table-title-group';

        const icon = document.createElement('div');
        icon.className = 'collapse-icon';
        icon.textContent = '▼';

        const title = document.createElement('div');
        title.className = 'table-title';
        title.textContent = this.table.title;

        titleGroup.appendChild(icon);
        titleGroup.appendChild(title);

        // Edit Mode: Rename Table Button
        if (GlobalStateManager.getInstance().isEditModeActive()) {
            const renameBtn = document.createElement('div');
            renameBtn.className = 'table-title-edit-btn';
            renameBtn.innerHTML = '✎';
            renameBtn.title = 'Tabelle umbenennen';
            renameBtn.onclick = (e) => {
                e.stopPropagation();
                const newTitle = prompt('Neuer Tabellentitel:', this.table.title);
                if (newTitle && newTitle.trim()) {
                    this.table.title = newTitle.trim();
                    title.textContent = newTitle.trim();
                    GlobalStateManager.getInstance().saveTableConfigs();
                }
            };
            titleGroup.appendChild(renameBtn);
        }

        const metaGroup = document.createElement('div');
        metaGroup.style.display = 'flex';
        metaGroup.style.alignItems = 'center';
        metaGroup.style.gap = '12px';

        const meta = document.createElement('span');
        meta.className = 'table-meta';
        meta.dataset.role = 'row-count';
        meta.textContent = `${this.table.rows.length} Zeilen`;
        metaGroup.appendChild(meta);

        // Edit Mode: Add Column Button next to row count
        if (GlobalStateManager.getInstance().isEditModeActive()) {
            const addColBtn = document.createElement('button');
            addColBtn.className = 'edit-mode-action-btn';
            addColBtn.innerHTML = '+ Spalte hinzufügen';
            addColBtn.onclick = async (e) => {
                e.stopPropagation();
                const gs = GlobalStateManager.getInstance();
                const enums = Object.keys(gs.getEnums());
                const res = await Dialog.showAddColumnDialog(this.table.id, enums);
                if (res) {
                    try { await gs.addColumn(this.table.id, res); } catch (err) {}
                }
            };
            metaGroup.appendChild(addColBtn);
        }

        header.appendChild(titleGroup);
        header.appendChild(metaGroup);

        if (this.table.rows.length === 0) {
            icon.textContent = '▸';
        }

        header.addEventListener('click', () => {

            this.element.classList.toggle('collapsed');
            icon.innerHTML = this.element.classList.contains('collapsed') ? '▸' : '▾';
        });

        header.addEventListener('contextmenu', (e) => {
            e.preventDefault();
            e.stopPropagation();
            this._showTableContextMenu(e);
        });

        return header;
    }

    _showTableContextMenu(e) {
        const existingMenu = document.querySelector('.category-context-menu');
        if (existingMenu) existingMenu.remove();

        const menu = document.createElement('div');
        menu.className = 'row-context-menu category-context-menu';
        menu.style.left = `${e.clientX}px`; menu.style.top = `${e.clientY}px`;
        menu.style.position = 'fixed'; menu.style.zIndex = '100000';

        const exportBtn = document.createElement('button');
        exportBtn.className = 'context-menu-item';
        exportBtn.textContent = 'Als PDF exportieren';
        exportBtn.onclick = () => { this._exportPDF(); menu.remove(); };
        menu.appendChild(exportBtn);

        const exportAllBtn = document.createElement('button');
        exportAllBtn.className = 'context-menu-item';
        exportAllBtn.textContent = 'Alle als PDF exportieren';
        exportAllBtn.style.fontStyle = 'italic';
        exportAllBtn.onclick = () => {
            const category = this.table.tableConfig?.category;
            let categoryId = category ? `all-${category}` : null;
            if (this.table.id === 'tbl_people' || this.table.id === 'people_table') categoryId = 'all-people';
            if (this.table.id === 'tbl_inventory') categoryId = 'all-inventory';

            if (categoryId) {
                window.dispatchEvent(new CustomEvent('export-category-pdf', { detail: { categoryId } }));
            }
            menu.remove();
        };
        menu.appendChild(exportAllBtn);

        const divider = document.createElement('div');
        divider.className = 'context-menu-divider';
        menu.appendChild(divider);

        const filterLocalBtn = document.createElement('button');
        filterLocalBtn.className = 'context-menu-item';
        filterLocalBtn.textContent = 'Filter für diese Tabelle';
        filterLocalBtn.onclick = () => {
            this.table.localFilters.active = !this.table.localFilters.active;
            this.filterBar.refresh();
            menu.remove();
        };
        menu.appendChild(filterLocalBtn);

        const filterAllBtn = document.createElement('button');
        filterAllBtn.className = 'context-menu-item';
        filterAllBtn.textContent = 'Filter für alle Tabellen';
        filterAllBtn.style.fontStyle = 'italic';
        filterAllBtn.onclick = () => {
            const isSplit = this.element.closest('.split-container-inner') !== null;
            const side = isSplit ? 'split' : 'main';
            window.dispatchEvent(new CustomEvent('toggle-filter-bar', { detail: { side } }));
            menu.remove();
        };
        menu.appendChild(filterAllBtn);

        document.body.appendChild(menu);
        const closeMenu = (ev) => { if (!menu.contains(ev.target)) { menu.remove(); document.removeEventListener('click', closeMenu); } };
        setTimeout(() => document.addEventListener('click', closeMenu), 0);
    }

    _renderTableScroll() {
        const scroll = document.createElement('div');
        scroll.className = 'table-scroll';
        const table = document.createElement('table');
        table.className = 'data-table';
        table.appendChild(this._renderTableHead());
        table.appendChild(this._renderTableBody());
        scroll.appendChild(table);
        return scroll;
    }

    _renderTableHead() {
        const thead = document.createElement('thead');
        const tr = document.createElement('tr');

        const chkTh = document.createElement('th');
        chkTh.className = 'bulk-col-header';
        chkTh.style.width = '40px';
        const chkAll = document.createElement('input');
        chkAll.type = 'checkbox';
        chkAll.onchange = (e) => {
            const isChecked = e.target.checked;
            this.selectedRows.clear();
            this.element.querySelectorAll('tbody tr[data-row-id]').forEach(rowEl => {
                const cb = rowEl.querySelector('.bulk-checkbox');
                if (cb) {
                    cb.checked = isChecked;
                    if (isChecked) this.selectedRows.add(rowEl.dataset.rowId);
                }
            });
            this._updateBulkBarVisibility();
        };
        chkTh.appendChild(chkAll);
        tr.appendChild(chkTh);

        const favTh = document.createElement('th');
        favTh.className = 'favorite-col-header';
        favTh.textContent = '★';
        tr.appendChild(favTh);

        this.table.schema.forEach((col, index) => {
            const th = document.createElement('th');
            th.dataset.colId = col.id;
            th.dataset.type = col.type || 'text';
            th.onclick = () => this.table.sorter.sortBy(col.id, th);
            const content = document.createElement('div');
            content.className = 'th-content';
            const textSpan = document.createElement('span');
            textSpan.textContent = col.label;
            content.appendChild(textSpan);
            th.appendChild(content);

            if (GlobalStateManager.getInstance().isEditModeActive()) {
                const controls = document.createElement('div');
                controls.className = 'col-edit-controls';
                const leftBtn = document.createElement('button'); leftBtn.textContent = '←'; leftBtn.onclick = (e) => { e.stopPropagation(); this._moveColumn(index, -1); };
                const renameBtn = document.createElement('button'); renameBtn.textContent = '✎'; renameBtn.onclick = (e) => { e.stopPropagation(); const l = prompt('Name:', col.label); if (l) { col.label = l.trim(); this.render(); GlobalStateManager.getInstance().saveTableConfigs(); } };
                const rightBtn = document.createElement('button'); rightBtn.textContent = '→'; rightBtn.onclick = (e) => { e.stopPropagation(); this._moveColumn(index, 1); };
                    const deleteBtn = document.createElement('button'); deleteBtn.textContent = '✖'; deleteBtn.onclick = async (e) => { e.stopPropagation(); if (await Dialog.confirm({ message: 'Löschen?' })) { try { await GlobalStateManager.getInstance().removeColumn(this.table.id, col.id); } catch(err){} } };

                controls.append(leftBtn, renameBtn, rightBtn, deleteBtn);
                th.appendChild(controls);
            }
            const resizer = document.createElement('div');
            resizer.className = 'col-resizer';
            this._setupColumnResizing(th, resizer);
            th.appendChild(resizer);
            tr.appendChild(th);
        });

        thead.appendChild(tr);
        return thead;
    }

    _moveColumn(index, delta) {
        const newIdx = index + delta;
        if (newIdx < 0 || newIdx >= this.table.schema.length) return;
        const item = this.table.schema.splice(index, 1)[0];
        this.table.schema.splice(newIdx, 0, item);
        this.render();
        GlobalStateManager.getInstance().saveTableConfigs();
    }

    _setupColumnResizing(th, resizer) {
        let x = 0; let w = 0;
        const mm = (e) => { const dx = e.clientX - x; th.style.width = `${w + dx}px`; th.style.minWidth = `${w + dx}px`; };
        const mu = () => { document.removeEventListener('mousemove', mm); document.removeEventListener('mouseup', mu); resizer.classList.remove('resizing'); };
        resizer.addEventListener('mousedown', (e) => { e.stopPropagation(); x = e.clientX; w = parseInt(window.getComputedStyle(th).width, 10); document.addEventListener('mousemove', mm); document.addEventListener('mouseup', mu); resizer.classList.add('resizing'); });
    }

    _renderTableBody() {
        const tbody = document.createElement('tbody');
        this.table._tbody = tbody;
        const gs = GlobalStateManager.getInstance();
        // 1. Resolve Filter State
        const side = this.element?.closest('.split-container-inner') ? 'split' : 'main';

        // Resolve the correct filter ID:
        // Priority 1: Check if there's a collective filter for this table's category (e.g., 'all-spiele')
        const category = this.table.tableConfig?.category;
        let globalFilterId = this.table.id;

        if (category) {
            const catId = `all-${category}`;
            const catFilter = gs.getGlobalFilterState(side, catId);
            if (catFilter && catFilter.active) {
                globalFilterId = catId;
            }
        }

        // Priority 2: Fallback to the explicit wrapper ID if no category match
        const viewWrapper = this.element?.closest('.table-view-wrapper');
        if (globalFilterId === this.table.id && viewWrapper && viewWrapper.dataset.tableId && viewWrapper.dataset.tableId.startsWith('all-')) {
            globalFilterId = viewWrapper.dataset.tableId;
        }

        const globalFilter = gs.getGlobalFilterState(side, globalFilterId);

        const localFilter = this.table.localFilters;

        // 2. Filter Rows (Hierarchical)
        let filteredRows = this.table.rows;

        // A) Apply Global Filter
        if (gs.isFavoritesFilterActive()) {
            filteredRows = filteredRows.filter(r => gs.isFavorite(r.id));
        }
        if (globalFilter.active) {
            filteredRows = filteredRows.filter(row => FilterEngine.matchesFilters(row, globalFilter.filters));
        }

        // B) Update Local Filter Bar context
        // We pass the full global filter object so the local bar can enforce Parent -> Child constraints.
        if (this.filterBar) {
            this.filterBar.updateRows(filteredRows, globalFilter);
        }




        // C) Apply Local Filter
        if (localFilter.active) {
            filteredRows = filteredRows.filter(row => FilterEngine.matchesFilters(row, localFilter.filters));
        }



        if (filteredRows.length === 0) {
            const tr = document.createElement('tr');
            tr.innerHTML = `<td colspan="${this.table.schema.length + 2}" style="text-align:center; padding: 40px; color: var(--text-muted);">Keine Einträge gefunden</td>`;
            tbody.appendChild(tr);
            this._renderAddRowButton(tbody);
            return tbody;
        }

        // 2. Group Rows
        // Priority: local grouping, then global grouping if active
        let groupBy = localFilter.active ? localFilter.groupBy : null;
        if (!groupBy && globalFilter.active) groupBy = globalFilter.groupBy;

        if (groupBy) {
            const groups = FilterEngine.groupRows(filteredRows, groupBy);
            const groupAttr = this.table.schema.find(s => s.id === groupBy);
            const attrLabel = groupAttr ? groupAttr.label : groupBy;

            Object.entries(groups).forEach(([groupName, rows]) => {
                // Render Group Header
                const gtr = document.createElement('tr');
                gtr.className = 'group-header-row';
                const gtd = document.createElement('td');
                gtd.className = 'group-header-cell';
                gtd.colSpan = this.table.schema.length + 2;

                gtd.innerHTML = `
                    <div class="group-header-content">
                        <span class="group-toggle-icon">▾</span>
                        <span class="group-attr-label">${attrLabel}</span>
                        <span class="group-name">${groupName}</span>
                        <span class="group-count">${rows.length}</span>
                    </div>
                `;

                // Click to collapse/expand the group
                gtd.addEventListener('click', () => {
                    const icon = gtd.querySelector('.group-toggle-icon');
                    const isCollapsed = gtr.classList.toggle('group-collapsed');
                    icon.textContent = isCollapsed ? '▸' : '▾';
                    // Toggle visibility of subsequent rows until next group header
                    let next = gtr.nextElementSibling;
                    while (next && !next.classList.contains('group-header-row') && !next.classList.contains('add-row-tr')) {
                        next.style.display = isCollapsed ? 'none' : '';
                        next = next.nextElementSibling;
                    }
                });

                gtr.appendChild(gtd);
                tbody.appendChild(gtr);

                // Render Rows for this group
                rows.forEach(row => {
                    this._setupRowCallbacks(row);
                    tbody.appendChild(row.render());
                });
            });
        } else {
            // No grouping
            filteredRows.forEach(row => {
                this._setupRowCallbacks(row);
                tbody.appendChild(row.render());
            });
        }

        this._renderAddRowButton(tbody);
        return tbody;
    }

    _setupRowCallbacks(row) {
        row.setCallbacks({
            onEditChange: () => this.table.editor.showUnsavedChange(),
            onDelete:     (rowId) => this.table.dataManager.removeRow(rowId),
            onSelect:     (rowId, s) => { 
                if (s) this.selectedRows.add(rowId); 
                else this.selectedRows.delete(rowId); 
                this._updateBulkBarVisibility(); 
            }
        });
    }


    _renderAddRowButton(tbody) {
        if (!GlobalStateManager.getInstance().canEdit(this.table.id)) return;
        const tr = document.createElement('tr');
        tr.className = 'add-row-tr';
        const td = document.createElement('td');
        td.colSpan = this.table.schema.length + 2;
        td.className = 'add-row-cell';
        const btn = document.createElement('button');
        btn.className = 'add-row-btn';
        btn.textContent = 'Zeile hinzufügen';
        btn.onclick = () => this.table.dataManager.addEmptyRow();
        td.appendChild(btn);
        tr.appendChild(td);
        tbody.appendChild(tr);
    }

    updateMeta() {
        const meta = this.element?.querySelector('[data-role="row-count"]');
        if (meta) meta.textContent = `${this.table.rows.length} Zeilen`;
        const ids = new Set(this.table.rows.map(r => r.id));
        for (const id of this.selectedRows) if (!ids.has(id)) this.selectedRows.delete(id);
        this._updateBulkBarVisibility();
    }

    async _exportPDF() {
        try {
            const gs = GlobalStateManager.getInstance();

            const side = this.element?.closest('.split-container-inner') ? 'split' : 'main';

            // Resolve Filter State (Global + Local)
            const category = this.table.tableConfig?.category;
            let globalFilterId = this.table.id;
            if (category) {
                const catId = `all-${category}`;
                const catFilter = gs.getGlobalFilterState(side, catId);
                if (catFilter && catFilter.active) globalFilterId = catId;
            }
            const viewWrapper = this.element?.closest('.table-view-wrapper');
            if (globalFilterId === this.table.id && viewWrapper && viewWrapper.dataset.tableId && viewWrapper.dataset.tableId.startsWith('all-')) {
                globalFilterId = viewWrapper.dataset.tableId;
            }

            const globalFilter = gs.getGlobalFilterState(side, globalFilterId);
            const localFilter = this.table.localFilters;

            const isFiltered = (globalFilter && globalFilter.active) || (localFilter && localFilter.active) || gs.isFavoritesFilterActive();

            if (isFiltered) {
                const proceed = await Dialog.confirm({
                    title: 'Export-Bestätigung',
                    message: 'Der Export beinhaltet nur die aktuell gefilterten Ergebnisse. Fortfahren?',
                    confirmText: 'Exportieren'
                });
                if (!proceed) return;
            }

            const doc = new jsPDF({ orientation: 'landscape', format: 'a3' });
            let currentY = 20;

            doc.setFontSize(18); doc.setFont(undefined, 'bold');
            doc.text(this.table.title || 'Export', 14, currentY);
            currentY += 8;

            // Render Filter Info in Header
            if (isFiltered) {
                doc.setFontSize(9); doc.setFont(undefined, 'normal'); doc.setTextColor(100);
                let filterText = 'Aktive Filter: ';
                const activeCriteria = [];

                if (gs.isFavoritesFilterActive()) activeCriteria.push('Nur Favoriten');

                if (globalFilter.active) {
                    globalFilter.filters.forEach(f => {
                        if (f.attrId) {
                            const p = [];
                            const val = Array.isArray(f.value) ? f.value.join(', ') : f.value;
                            if (val) p.push(`${f.attrId} ${f.mode || 'ist'} ${val}`);
                            if (f.quantityMode && f.quantityMode !== 'any' && f.quantityValue) p.push(`Anzahl ${f.quantityMode} ${f.quantityValue}`);
                            if (Array.isArray(f.availability) && f.availability.length > 0) p.push(`Verfügbarkeit: ${f.availability.join(', ')}`);
                            if (p.length > 0) activeCriteria.push(`[Global] ${p.join(' & ')}`);
                        }
                    });
                }

                if (localFilter.active) {
                    localFilter.filters.forEach(f => {
                        if (f.attrId) {
                            const p = [];
                            const val = Array.isArray(f.value) ? f.value.join(', ') : f.value;
                            if (val) p.push(`${f.attrId} ${f.mode || 'ist'} ${val}`);
                            if (f.quantityMode && f.quantityMode !== 'any' && f.quantityValue) p.push(`Anzahl ${f.quantityMode} ${f.quantityValue}`);
                            if (Array.isArray(f.availability) && f.availability.length > 0) p.push(`Verfügbarkeit: ${f.availability.join(', ')}`);
                            if (p.length > 0) activeCriteria.push(`[Lokal] ${p.join(' & ')}`);
                        }
                    });
                }


                doc.text(filterText + activeCriteria.join(' | '), 14, currentY);
                currentY += 10;
                doc.setTextColor(0);
            } else {
                currentY += 2;
            }

            const ignore = ['Erstellt von', 'Erstellt am', 'createdAt', 'createdBy', 'Link/Video/Lied'];
            const schema = this.table.schema.filter(c => !ignore.includes(c.label) && !ignore.includes(c.id));
            const head = [schema.map(c => c.label)];

            // Filter Rows logic
            let filteredRows = this.table.rows;
            if (gs.isFavoritesFilterActive()) filteredRows = filteredRows.filter(r => gs.isFavorite(r.id));
            if (globalFilter.active) filteredRows = filteredRows.filter(row => FilterEngine.matchesFilters(row, globalFilter.filters));
            if (localFilter.active) filteredRows = filteredRows.filter(row => FilterEngine.matchesFilters(row, localFilter.filters));

            const body = filteredRows.map(row => schema.map(c => {
                let v = row.data[c.id]; if (v === null || v === undefined) return '';
                let s = typeof v === 'object' ? (Array.isArray(v) ? v.map(i => typeof i === 'object' ? i.name || i.id : i).join(', ') : (v.title || v.name || JSON.stringify(v))) : String(v);
                return s.length > 250 ? s.substring(0, 247) + '...' : s;
            }));

            autoTable(doc, { 
                head, 
                body, 
                startY: currentY, 
                styles: { fontSize: 8, cellPadding: 3, overflow: 'linebreak' }, 
                headStyles: { fillColor: [0, 132, 255] } 
            });

            window.open(doc.output('bloburl'), '_blank');
        } catch (e) {
            console.error('PDF export failed', e);
            alert('Fehler beim PDF Export: ' + e.message);
        }
    }

    _renderBulkActionsBar() {
        const bar = document.createElement('div');
        bar.className = 'bulk-actions-bar';
        bar.style.cssText = 'display:none; position:fixed; bottom:20px; left:50%; transform:translateX(-50%); background:var(--bg); padding:12px 24px; border-radius:var(--radius); box-shadow:var(--shadow-lg); border:1px solid var(--border); z-index:1000; align-items:center; gap:16px;';
        const msg = document.createElement('span'); msg.className = 'bulk-actions-msg'; bar.appendChild(msg);
        const btn = document.createElement('button'); btn.textContent = 'Löschen (Bulk)'; btn.style.color = '#ff4d4d'; btn.onclick = async () => { if (await Dialog.confirm({ message: 'Löschen?' })) { for (const id of this.selectedRows) this.table.dataManager.removeRow(id); this.selectedRows.clear(); this._updateBulkBarVisibility(); } };

        const close = document.createElement('button'); close.textContent = '✕'; close.onclick = () => { this.selectedRows.clear(); this.element.querySelectorAll('.bulk-checkbox').forEach(c => c.checked = false); this._updateBulkBarVisibility(); };
        bar.append(btn, close);
        return bar;
    }

    _updateBulkBarVisibility() {
        if (!this.bulkBar) return;
        if (this.selectedRows.size > 0) {
            this.bulkBar.style.display = 'flex';
            this.bulkBar.querySelector('.bulk-actions-msg').textContent = `${this.selectedRows.size} ausgewählt`;
        } else { this.bulkBar.style.display = 'none'; }
    }
}

import '../styles/Table.css';
import '../styles/FilterBar.css';
import { GlobalStateManager } from './GlobalStateManager.js';
import { FilterEngine } from '../utils/FilterEngine.js';
import { Dialog } from '../ui/Dialog.js';

import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { FilterBar } from '../ui/FilterBar.js';

/**
 * TableRenderer - Handles rendering and updating the table UI
 */
export class TableRenderer {
    constructor(table) {
        this.table = table;
        this.element = null;
        this.selectedRows = new Set();
        this.filterBar = null;
    }

    render() {
        this.element = document.createElement('div');
        this.element.className = 'table-wrapper';

        this.element.appendChild(this._renderHeader());

        // Local Filter Bar
        this.filterBar = new FilterBar({
            schema: this.table.schema,
            state: this.table.localFilters,
            tableId: this.table.id,
            onUpdate: () => this.update()
        });

        this.element.appendChild(this.filterBar.render());

        // Context menu on the filter bar itself
        this.filterBar.element.addEventListener('contextmenu', (e) => {
            e.preventDefault();
            e.stopPropagation();
            this._showTableContextMenu(e);
        });

        this.element.appendChild(this._renderTableScroll());

        this.bulkBar = this._renderBulkActionsBar();
        this.element.appendChild(this.bulkBar);

        // Auto-collapse if empty
        if (this.table.rows.length === 0) {
            this.element.classList.add('collapsed');
        }

        return this.element;
    }


    update() {
        if (!this.element) return;
        this.updateMeta();

        const oldBody = this.element.querySelector('tbody');
        if (oldBody) {
            const newBody = this._renderTableBody();
            oldBody.replaceWith(newBody);
        }
    }

    _renderHeader() {
        const header = document.createElement('div');
        header.className = 'table-top';
        header.style.cursor = 'pointer';
        header.title = 'Klicken zum Ein-/Ausklappen';

        const titleGroup = document.createElement('div');
        titleGroup.className = 'table-title-group';

        const icon = document.createElement('div');
        icon.className = 'collapse-icon';
        icon.textContent = '▼';

        const title = document.createElement('div');
        title.className = 'table-title';
        title.textContent = this.table.title;

        titleGroup.appendChild(icon);
        titleGroup.appendChild(title);

        // Edit Mode: Rename Table Button
        if (GlobalStateManager.getInstance().isEditModeActive()) {
            const renameBtn = document.createElement('div');
            renameBtn.className = 'table-title-edit-btn';
            renameBtn.innerHTML = '✎';
            renameBtn.title = 'Tabelle umbenennen';
            renameBtn.onclick = (e) => {
                e.stopPropagation();
                const newTitle = prompt('Neuer Tabellentitel:', this.table.title);
                if (newTitle && newTitle.trim()) {
                    this.table.title = newTitle.trim();
                    title.textContent = newTitle.trim();
                    GlobalStateManager.getInstance().saveTableConfigs();
                }
            };
            titleGroup.appendChild(renameBtn);
        }

        const metaGroup = document.createElement('div');
        metaGroup.style.display = 'flex';
        metaGroup.style.alignItems = 'center';
        metaGroup.style.gap = '12px';

        const meta = document.createElement('span');
        meta.className = 'table-meta';
        meta.dataset.role = 'row-count';
        meta.textContent = `${this.table.rows.length} Zeilen`;
        metaGroup.appendChild(meta);

        // Edit Mode: Add Column Button next to row count
        if (GlobalStateManager.getInstance().isEditModeActive()) {
            const addColBtn = document.createElement('button');
            addColBtn.className = 'edit-mode-action-btn';
            addColBtn.innerHTML = '+ Spalte hinzufügen';
            addColBtn.onclick = async (e) => {
                e.stopPropagation();
                const gs = GlobalStateManager.getInstance();
                const enums = Object.keys(gs.getEnums());
                const res = await Dialog.showAddColumnDialog(this.table.id, enums);
                if (res) {
                    try { await gs.addColumn(this.table.id, res); } catch (err) {}
                }
            };
            metaGroup.appendChild(addColBtn);
        }

        header.appendChild(titleGroup);
        header.appendChild(metaGroup);

        if (this.table.rows.length === 0) {
            icon.textContent = '▸';
        }

        header.addEventListener('click', () => {

            this.element.classList.toggle('collapsed');
            icon.innerHTML = this.element.classList.contains('collapsed') ? '▸' : '▾';
        });

        header.addEventListener('contextmenu', (e) => {
            e.preventDefault();
            e.stopPropagation();
            this._showTableContextMenu(e);
        });

        return header;
    }

    _showTableContextMenu(e) {
        const existingMenu = document.querySelector('.category-context-menu');
        if (existingMenu) existingMenu.remove();

        const menu = document.createElement('div');
        menu.className = 'row-context-menu category-context-menu';
        menu.style.left = `${e.clientX}px`; menu.style.top = `${e.clientY}px`;
        menu.style.position = 'fixed'; menu.style.zIndex = '100000';

        const exportBtn = document.createElement('button');
        exportBtn.className = 'context-menu-item';
        exportBtn.textContent = 'Als PDF exportieren';
        exportBtn.onclick = () => { this._exportPDF(); menu.remove(); };
        menu.appendChild(exportBtn);

        const exportAllBtn = document.createElement('button');
        exportAllBtn.className = 'context-menu-item';
        exportAllBtn.textContent = 'Alle als PDF exportieren';
        exportAllBtn.style.fontStyle = 'italic';
        exportAllBtn.onclick = () => {
            const category = this.table.tableConfig?.category;
            let categoryId = category ? `all-${category}` : null;
            if (this.table.id === 'tbl_people' || this.table.id === 'people_table') categoryId = 'all-people';
            if (this.table.id === 'tbl_inventory') categoryId = 'all-inventory';

            if (categoryId) {
                window.dispatchEvent(new CustomEvent('export-category-pdf', { detail: { categoryId } }));
            }
            menu.remove();
        };
        menu.appendChild(exportAllBtn);

        const divider = document.createElement('div');
        divider.className = 'context-menu-divider';
        menu.appendChild(divider);

        const filterLocalBtn = document.createElement('button');
        filterLocalBtn.className = 'context-menu-item';
        filterLocalBtn.textContent = 'Filter für diese Tabelle';
        filterLocalBtn.onclick = () => {
            this.table.localFilters.active = !this.table.localFilters.active;
            this.filterBar.refresh();
            menu.remove();
        };
        menu.appendChild(filterLocalBtn);

        const filterAllBtn = document.createElement('button');
        filterAllBtn.className = 'context-menu-item';
        filterAllBtn.textContent = 'Filter für alle Tabellen';
        filterAllBtn.style.fontStyle = 'italic';
        filterAllBtn.onclick = () => {
            const isSplit = this.element.closest('.split-container-inner') !== null;
            const side = isSplit ? 'split' : 'main';
            window.dispatchEvent(new CustomEvent('toggle-filter-bar', { detail: { side } }));
            menu.remove();
        };
        menu.appendChild(filterAllBtn);

        document.body.appendChild(menu);
        const closeMenu = (ev) => { if (!menu.contains(ev.target)) { menu.remove(); document.removeEventListener('click', closeMenu); } };
        setTimeout(() => document.addEventListener('click', closeMenu), 0);
    }

    _renderTableScroll() {
        const scroll = document.createElement('div');
        scroll.className = 'table-scroll';
        const table = document.createElement('table');
        table.className = 'data-table';
        table.appendChild(this._renderTableHead());
        table.appendChild(this._renderTableBody());
        scroll.appendChild(table);
        return scroll;
    }

    _renderTableHead() {
        const thead = document.createElement('thead');
        const tr = document.createElement('tr');

        const chkTh = document.createElement('th');
        chkTh.className = 'bulk-col-header';
        chkTh.style.width = '40px';
        const chkAll = document.createElement('input');
        chkAll.type = 'checkbox';
        chkAll.onchange = (e) => {
            const isChecked = e.target.checked;
            this.selectedRows.clear();
            this.element.querySelectorAll('tbody tr[data-row-id]').forEach(rowEl => {
                const cb = rowEl.querySelector('.bulk-checkbox');
                if (cb) {
                    cb.checked = isChecked;
                    if (isChecked) this.selectedRows.add(rowEl.dataset.rowId);
                }
            });
            this._updateBulkBarVisibility();
        };
        chkTh.appendChild(chkAll);
        tr.appendChild(chkTh);

        const favTh = document.createElement('th');
        favTh.className = 'favorite-col-header';
        favTh.textContent = '★';
        tr.appendChild(favTh);

        this.table.schema.forEach((col, index) => {
            const th = document.createElement('th');
            th.dataset.colId = col.id;
            th.dataset.type = col.type || 'text';
            th.onclick = () => this.table.sorter.sortBy(col.id, th);
            const content = document.createElement('div');
            content.className = 'th-content';
            const textSpan = document.createElement('span');
            textSpan.textContent = col.label;
            content.appendChild(textSpan);
            th.appendChild(content);

            if (GlobalStateManager.getInstance().isEditModeActive()) {
                const controls = document.createElement('div');
                controls.className = 'col-edit-controls';
                const leftBtn = document.createElement('button'); leftBtn.textContent = '←'; leftBtn.onclick = (e) => { e.stopPropagation(); this._moveColumn(index, -1); };
                const renameBtn = document.createElement('button'); renameBtn.textContent = '✎'; renameBtn.onclick = (e) => { e.stopPropagation(); const l = prompt('Name:', col.label); if (l) { col.label = l.trim(); this.render(); GlobalStateManager.getInstance().saveTableConfigs(); } };
                const rightBtn = document.createElement('button'); rightBtn.textContent = '→'; rightBtn.onclick = (e) => { e.stopPropagation(); this._moveColumn(index, 1); };
                    const deleteBtn = document.createElement('button'); deleteBtn.textContent = '✖'; deleteBtn.onclick = async (e) => { e.stopPropagation(); if (await Dialog.confirm({ message: 'Löschen?' })) { try { await GlobalStateManager.getInstance().removeColumn(this.table.id, col.id); } catch(err){} } };

                controls.append(leftBtn, renameBtn, rightBtn, deleteBtn);
                th.appendChild(controls);
            }
            const resizer = document.createElement('div');
            resizer.className = 'col-resizer';
            this._setupColumnResizing(th, resizer);
            th.appendChild(resizer);
            tr.appendChild(th);
        });

        thead.appendChild(tr);
        return thead;
    }

    _moveColumn(index, delta) {
        const newIdx = index + delta;
        if (newIdx < 0 || newIdx >= this.table.schema.length) return;
        const item = this.table.schema.splice(index, 1)[0];
        this.table.schema.splice(newIdx, 0, item);
        this.render();
        GlobalStateManager.getInstance().saveTableConfigs();
    }

    _setupColumnResizing(th, resizer) {
        let x = 0; let w = 0;
        const mm = (e) => { const dx = e.clientX - x; th.style.width = `${w + dx}px`; th.style.minWidth = `${w + dx}px`; };
        const mu = () => { document.removeEventListener('mousemove', mm); document.removeEventListener('mouseup', mu); resizer.classList.remove('resizing'); };
        resizer.addEventListener('mousedown', (e) => { e.stopPropagation(); x = e.clientX; w = parseInt(window.getComputedStyle(th).width, 10); document.addEventListener('mousemove', mm); document.addEventListener('mouseup', mu); resizer.classList.add('resizing'); });
    }

    _renderTableBody() {
        const tbody = document.createElement('tbody');
        this.table._tbody = tbody;
        const gs = GlobalStateManager.getInstance();
        // 1. Resolve Filter State
        const side = this.element?.closest('.split-container-inner') ? 'split' : 'main';

        // Resolve the correct filter ID:
        // Priority 1: Check if there's a collective filter for this table's category (e.g., 'all-spiele')
        const category = this.table.tableConfig?.category;
        let globalFilterId = this.table.id;

        if (category) {
            const catId = `all-${category}`;
            const catFilter = gs.getGlobalFilterState(side, catId);
            if (catFilter && catFilter.active) {
                globalFilterId = catId;
            }
        }

        // Priority 2: Fallback to the explicit wrapper ID if no category match
        const viewWrapper = this.element?.closest('.table-view-wrapper');
        if (globalFilterId === this.table.id && viewWrapper && viewWrapper.dataset.tableId && viewWrapper.dataset.tableId.startsWith('all-')) {
            globalFilterId = viewWrapper.dataset.tableId;
        }

        const globalFilter = gs.getGlobalFilterState(side, globalFilterId);

        const localFilter = this.table.localFilters;

        // 2. Filter Rows (Hierarchical)
        let filteredRows = this.table.rows;

        // A) Apply Global Filter
        if (gs.isFavoritesFilterActive()) {
            filteredRows = filteredRows.filter(r => gs.isFavorite(r.id));
        }
        if (globalFilter.active) {
            filteredRows = filteredRows.filter(row => FilterEngine.matchesFilters(row, globalFilter.filters));
        }

        // B) Update Local Filter Bar context
        // We pass the full global filter object so the local bar can enforce Parent -> Child constraints.
        if (this.filterBar) {
            this.filterBar.updateRows(filteredRows, globalFilter);
        }




        // C) Apply Local Filter
        if (localFilter.active) {
            filteredRows = filteredRows.filter(row => FilterEngine.matchesFilters(row, localFilter.filters));
        }



        if (filteredRows.length === 0) {
            const tr = document.createElement('tr');
            tr.innerHTML = `<td colspan="${this.table.schema.length + 2}" style="text-align:center; padding: 40px; color: var(--text-muted);">Keine Einträge gefunden</td>`;
            tbody.appendChild(tr);
            this._renderAddRowButton(tbody);
            return tbody;
        }

        // 2. Group Rows
        // Priority: local grouping, then global grouping if active
        let groupBy = localFilter.active ? localFilter.groupBy : null;
        if (!groupBy && globalFilter.active) groupBy = globalFilter.groupBy;

        if (groupBy) {
            const groups = FilterEngine.groupRows(filteredRows, groupBy);
            const groupAttr = this.table.schema.find(s => s.id === groupBy);
            const attrLabel = groupAttr ? groupAttr.label : groupBy;

            Object.entries(groups).forEach(([groupName, rows]) => {
                // Render Group Header
                const gtr = document.createElement('tr');
                gtr.className = 'group-header-row';
                const gtd = document.createElement('td');
                gtd.className = 'group-header-cell';
                gtd.colSpan = this.table.schema.length + 2;

                gtd.innerHTML = `
                    <div class="group-header-content">
                        <span class="group-toggle-icon">▾</span>
                        <span class="group-attr-label">${attrLabel}</span>
                        <span class="group-name">${groupName}</span>
                        <span class="group-count">${rows.length}</span>
                    </div>
                `;

                // Click to collapse/expand the group
                gtd.addEventListener('click', () => {
                    const icon = gtd.querySelector('.group-toggle-icon');
                    const isCollapsed = gtr.classList.toggle('group-collapsed');
                    icon.textContent = isCollapsed ? '▸' : '▾';
                    // Toggle visibility of subsequent rows until next group header
                    let next = gtr.nextElementSibling;
                    while (next && !next.classList.contains('group-header-row') && !next.classList.contains('add-row-tr')) {
                        next.style.display = isCollapsed ? 'none' : '';
                        next = next.nextElementSibling;
                    }
                });

                gtr.appendChild(gtd);
                tbody.appendChild(gtr);

                // Render Rows for this group
                rows.forEach(row => {
                    this._setupRowCallbacks(row);
                    tbody.appendChild(row.render());
                });
            });
        } else {
            // No grouping
            filteredRows.forEach(row => {
                this._setupRowCallbacks(row);
                tbody.appendChild(row.render());
            });
        }

        this._renderAddRowButton(tbody);
        return tbody;
    }

    _setupRowCallbacks(row) {
        row.setCallbacks({
            onEditChange: () => this.table.editor.showUnsavedChange(),
            onDelete:     (rowId) => this.table.dataManager.removeRow(rowId),
            onSelect:     (rowId, s) => { 
                if (s) this.selectedRows.add(rowId); 
                else this.selectedRows.delete(rowId); 
                this._updateBulkBarVisibility(); 
            }
        });
    }


    _renderAddRowButton(tbody) {
        if (!GlobalStateManager.getInstance().canEdit(this.table.id)) return;
        const tr = document.createElement('tr');
        tr.className = 'add-row-tr';
        const td = document.createElement('td');
        td.colSpan = this.table.schema.length + 2;
        td.className = 'add-row-cell';
        const btn = document.createElement('button');
        btn.className = 'add-row-btn';
        btn.textContent = 'Zeile hinzufügen';
        btn.onclick = () => this.table.dataManager.addEmptyRow();
        td.appendChild(btn);
        tr.appendChild(td);
        tbody.appendChild(tr);
    }

    updateMeta() {
        const meta = this.element?.querySelector('[data-role="row-count"]');
        if (meta) meta.textContent = `${this.table.rows.length} Zeilen`;
        const ids = new Set(this.table.rows.map(r => r.id));
        for (const id of this.selectedRows) if (!ids.has(id)) this.selectedRows.delete(id);
        this._updateBulkBarVisibility();
    }

    async _exportPDF() {
        try {
            const gs = GlobalStateManager.getInstance();

            const side = this.element?.closest('.split-container-inner') ? 'split' : 'main';

            // Resolve Filter State (Global + Local)
            const category = this.table.tableConfig?.category;
            let globalFilterId = this.table.id;
            if (category) {
                const catId = `all-${category}`;
                const catFilter = gs.getGlobalFilterState(side, catId);
                if (catFilter && catFilter.active) globalFilterId = catId;
            }
            const viewWrapper = this.element?.closest('.table-view-wrapper');
            if (globalFilterId === this.table.id && viewWrapper && viewWrapper.dataset.tableId && viewWrapper.dataset.tableId.startsWith('all-')) {
                globalFilterId = viewWrapper.dataset.tableId;
            }

            const globalFilter = gs.getGlobalFilterState(side, globalFilterId);
            const localFilter = this.table.localFilters;

            const isFiltered = (globalFilter && globalFilter.active) || (localFilter && localFilter.active) || gs.isFavoritesFilterActive();

            if (isFiltered) {
                const proceed = await Dialog.confirm({
                    title: 'Export-Bestätigung',
                    message: 'Der Export beinhaltet nur die aktuell gefilterten Ergebnisse. Fortfahren?',
                    confirmText: 'Exportieren'
                });
                if (!proceed) return;
            }

            const doc = new jsPDF({ orientation: 'landscape', format: 'a3' });
            let currentY = 20;

            doc.setFontSize(18); doc.setFont(undefined, 'bold');
            doc.text(this.table.title || 'Export', 14, currentY);
            currentY += 8;

            // Render Filter Info in Header
            if (isFiltered) {
                doc.setFontSize(9); doc.setFont(undefined, 'normal'); doc.setTextColor(100);
                let filterText = 'Aktive Filter: ';
                const activeCriteria = [];

                if (gs.isFavoritesFilterActive()) activeCriteria.push('Nur Favoriten');

                if (globalFilter.active) {
                    globalFilter.filters.forEach(f => {
                        if (f.attrId) {
                            const p = [];
                            const val = Array.isArray(f.value) ? f.value.join(', ') : f.value;
                            if (val) p.push(`${f.attrId} ${f.mode || 'ist'} ${val}`);
                            if (f.quantityMode && f.quantityMode !== 'any' && f.quantityValue) p.push(`Anzahl ${f.quantityMode} ${f.quantityValue}`);
                            if (Array.isArray(f.availability) && f.availability.length > 0) p.push(`Verfügbarkeit: ${f.availability.join(', ')}`);
                            if (p.length > 0) activeCriteria.push(`[Global] ${p.join(' & ')}`);
                        }
                    });
                }

                if (localFilter.active) {
                    localFilter.filters.forEach(f => {
                        if (f.attrId) {
                            const p = [];
                            const val = Array.isArray(f.value) ? f.value.join(', ') : f.value;
                            if (val) p.push(`${f.attrId} ${f.mode || 'ist'} ${val}`);
                            if (f.quantityMode && f.quantityMode !== 'any' && f.quantityValue) p.push(`Anzahl ${f.quantityMode} ${f.quantityValue}`);
                            if (Array.isArray(f.availability) && f.availability.length > 0) p.push(`Verfügbarkeit: ${f.availability.join(', ')}`);
                            if (p.length > 0) activeCriteria.push(`[Lokal] ${p.join(' & ')}`);
                        }
                    });
                }


                doc.text(filterText + activeCriteria.join(' | '), 14, currentY);
                currentY += 10;
                doc.setTextColor(0);
            } else {
                currentY += 2;
            }

            const ignore = ['Erstellt von', 'Erstellt am', 'createdAt', 'createdBy', 'Link/Video/Lied'];
            const schema = this.table.schema.filter(c => !ignore.includes(c.label) && !ignore.includes(c.id));
            const head = [schema.map(c => c.label)];

            // Filter Rows logic
            let filteredRows = this.table.rows;
            if (gs.isFavoritesFilterActive()) filteredRows = filteredRows.filter(r => gs.isFavorite(r.id));
            if (globalFilter.active) filteredRows = filteredRows.filter(row => FilterEngine.matchesFilters(row, globalFilter.filters));
            if (localFilter.active) filteredRows = filteredRows.filter(row => FilterEngine.matchesFilters(row, localFilter.filters));

            const body = filteredRows.map(row => schema.map(c => {
                let v = row.data[c.id]; if (v === null || v === undefined) return '';
                let s = typeof v === 'object' ? (Array.isArray(v) ? v.map(i => typeof i === 'object' ? i.name || i.id : i).join(', ') : (v.title || v.name || JSON.stringify(v))) : String(v);
                return s.length > 250 ? s.substring(0, 247) + '...' : s;
            }));

            autoTable(doc, { 
                head, 
                body, 
                startY: currentY, 
                styles: { fontSize: 8, cellPadding: 3, overflow: 'linebreak' }, 
                headStyles: { fillColor: [0, 132, 255] } 
            });

            window.open(doc.output('bloburl'), '_blank');
        } catch (e) {
            console.error('PDF export failed', e);
            alert('Fehler beim PDF Export: ' + e.message);
        }
    }

    _bulkExportPDF() {
        if (this.selectedRows.size === 0) return;

        const rows = Array.from(this.selectedRows)
            .map(id => this.table.rows.find(r => r.id === id))
            .filter(r => r);

        if (rows.length === 0) return;

        // Prepare data for PDF
        const headers = this.table.schema.map(col => col.label);
        const body = rows.map(row => {
            return this.table.schema.map(col => {
                let val = row.data[col.id] ?? '';
                if (typeof val === 'object') {
                    val = Array.isArray(val) ? val.map(i => typeof i === 'object' ? i.name || i.id : i).join('; ') : (val.title || val.name || '');
                }
                return String(val);
            });
        });

        // Create PDF
        const doc = new jsPDF();
        doc.text(`${this.table.title || 'Export'} - ${rows.length} Zeilen`, 14, 20);

        autoTable(doc, {
            head: [headers],
            body: body,
            startY: 30,
            styles: {
                fontSize: 8,
                cellPadding: 2,
            },
            headStyles: {
                fillColor: [41, 128, 185], // Blue header
                textColor: 255,
                fontSize: 9,
                fontStyle: 'bold',
            },
            alternateRowStyles: {
                fillColor: [245, 245, 245], // Light gray alternate rows
            },
            margin: { top: 30 },
        });

        doc.save(`${this.table.title || 'export'}-bulk.pdf`);
    }

    _renderBulkActionsBar() {
        const bar = document.createElement('div');
        bar.className = 'bulk-actions-bar';
        bar.style.cssText = 'display:none; position:fixed; bottom:20px; left:50%; transform:translateX(-50%); background:var(--bg); padding:12px 16px; border-radius:var(--radius); box-shadow:var(--shadow-lg); border:1px solid var(--border); z-index:1000; align-items:center; gap:8px; flex-wrap:wrap; max-width:90vw;';

        const msg = document.createElement('span');
        msg.className = 'bulk-actions-msg';
        msg.style.fontWeight = 'bold';
        msg.style.marginRight = '8px';
        bar.appendChild(msg);

        // Export button
        const exportBtn = document.createElement('button');
        exportBtn.className = 'nav-btn';
        exportBtn.textContent = 'Exportieren';
        exportBtn.title = 'Ausgewählte Zeilen als PDF exportieren';
        exportBtn.onclick = () => this._bulkExportPDF();
        bar.appendChild(exportBtn);

        // Delete button
        const deleteBtn = document.createElement('button');
        deleteBtn.className = 'discard-btn-header';
        deleteBtn.textContent = 'Löschen';
        deleteBtn.title = 'Ausgewählte Zeilen löschen';
        deleteBtn.onclick = async () => {
            if (await Dialog.confirm({ message: `${this.selectedRows.size} Zeilen löschen?`, confirmText: 'Löschen', confirmStyle: 'warning' })) {
                for (const id of this.selectedRows) {
                    this.table.dataManager.removeRow(id);
                }
                this.selectedRows.clear();
                this._updateBulkBarVisibility();
            }
        };
        bar.appendChild(deleteBtn);

        // Close button
        const closeBtn = document.createElement('button');
        closeBtn.className = 'nav-btn';
        closeBtn.textContent = 'Schließen';
        closeBtn.title = 'Auswahl aufheben';
        closeBtn.onclick = () => {
            this.selectedRows.clear();
            this.element.querySelectorAll('.bulk-checkbox').forEach(c => c.checked = false);
            this._updateBulkBarVisibility();
        };
        bar.appendChild(closeBtn);

        return bar;
    }

    _updateBulkBarVisibility() {
        if (!this.bulkBar) return;
        if (this.selectedRows.size > 0) {
            this.bulkBar.style.display = 'flex';
            this.bulkBar.querySelector('.bulk-actions-msg').textContent = `${this.selectedRows.size} ausgewählt`;
        } else { this.bulkBar.style.display = 'none'; }
    }
}

import { SupabaseClient } from './SupabaseClient.js';
import { UserStatsService } from './UserStatsService.js';
import { GlobalStateManager } from '../core/GlobalStateManager.js';

/**
 * AuthService — Authentication against the relational `users` table.
 */
export class AuthService {

    /**
     * Authenticate or register a user.
     * - If the user does not exist in the `users` table, create a new row.
     * - If the user exists, validate the password.
     */
    static async authenticate(username, password) {
        const res = await SupabaseClient.get('users', `?username=eq.${encodeURIComponent(username)}&select=*`);
        if (!res.ok) throw new Error('Verbindung zu Supabase fehlgeschlagen');

        const rows = await res.json();

        if (rows.length === 0) {
            // Register new user
            const insertRes = await SupabaseClient.post('users', {
                username,
                password_hash: password, // In production, hash this!
                role: 'User',
            }, { 'Prefer': 'return=representation' });

            if (!insertRes.ok) {
                const txt = await insertRes.text();
                throw new Error(`Registrierung fehlgeschlagen: ${txt}`);
            }

            const newUser = (await insertRes.json())[0];
            await UserStatsService.recordLogin(newUser.id);
            return { success: true, username, userId: newUser.id, role: 'User' };
        }

        const user = rows[0];

        if (user.password_hash !== password) {
            throw new Error('Ungültiges Passwort');
        }

        await UserStatsService.recordLogin(user.id);
        return { success: true, username, userId: user.id, role: user.role || 'User' };
    }

    /**
     * Get user record by username.
     */
    static async getUserByUsername(username) {
        const res = await SupabaseClient.get('users', `?username=eq.${encodeURIComponent(username)}&select=*`);
        if (!res.ok) return null;
        const rows = await res.json();
        return rows[0] || null;
    }

    /**
     * Change password for a user.
     */
    static async changePassword(username, newPassword) {
        const res = await SupabaseClient.patch(
            'users',
            `?username=eq.${encodeURIComponent(username)}`,
            { password_hash: newPassword, password_last_changed: new Date().toISOString() }
        );

        if (!res.ok) throw new Error('Passwort-Änderung fehlgeschlagen');
        return { success: true };
    }

    /**
     * Save/Update permissions for a specific user.
     * Uses localStorage for now (same as before).
     */
    static savePermissions(targetUsername, permissions) {
        const permissionsMap = JSON.parse(localStorage.getItem('app_permissions_map') || '{}');
        permissionsMap[targetUsername] = permissions;
        localStorage.setItem('app_permissions_map', JSON.stringify(permissionsMap));

        const globalState = GlobalStateManager.getInstance();
        if (globalState.getCurrentUser() === targetUsername) {
            globalState.setPermissions(permissions);
        }
    }
}

import { SupabaseClient } from './SupabaseClient.js';
import { UserStatsService } from './UserStatsService.js';
import { GlobalStateManager } from '../core/GlobalStateManager.js';

/**
 * AuthService — Authentication against the relational `users` table.
 */
export class AuthService {

    /**
     * Authenticate or register a user.
     * - If the user does not exist in the `users` table, create a new row.
     * - If the user exists, validate the password.
     */
    static async authenticate(username, password) {
        const res = await SupabaseClient.get('users', `?username=eq.${encodeURIComponent(username)}&select=*`);
        if (!res.ok) throw new Error('Verbindung zu Supabase fehlgeschlagen');

        const rows = await res.json();

        if (rows.length === 0) {
            // Register new user
            const insertRes = await SupabaseClient.post('users', {
                username,
                password_hash: password,
                role: 'User',
            }, { 'Prefer': 'return=representation' });

            if (!insertRes.ok) {
                const txt = await insertRes.text();
                throw new Error(`Registrierung fehlgeschlagen: ${txt}`);
            }

            const newUser = (await insertRes.json())[0];
            await UserStatsService.recordLogin(newUser.id);
            return { success: true, username, userId: newUser.id, role: 'User' };
        }

        const user = rows[0];

        if (user.password_hash !== password) {
            throw new Error('Ungültiges Passwort');
        }

        await UserStatsService.recordLogin(user.id);
        return { success: true, username, userId: user.id, role: user.role || 'User' };
    }

    /**
     * Get user record by username.
     */
    static async getUserByUsername(username) {
        const res = await SupabaseClient.get('users', `?username=eq.${encodeURIComponent(username)}&select=*`);
        if (!res.ok) return null;
        const rows = await res.json();
        return rows[0] || null;
    }

    /**
     * Change password for a user.
     */
    static async changePassword(username, newPassword) {
        const res = await SupabaseClient.patch(
            'users',
            `?username=eq.${encodeURIComponent(username)}`,
            { password_hash: newPassword, password_last_changed: new Date().toISOString() }
        );

        if (!res.ok) throw new Error('Passwort-Änderung fehlgeschlagen');
        return { success: true };
    }

    /**
     * Save/Update permissions for a specific user.
     * Uses localStorage for now (same as before).
     */
    static savePermissions(targetUsername, permissions) {
        const permissionsMap = JSON.parse(localStorage.getItem('app_permissions_map') || '{}');
        permissionsMap[targetUsername] = permissions;
        localStorage.setItem('app_permissions_map', JSON.stringify(permissionsMap));

        const globalState = GlobalStateManager.getInstance();
        if (globalState.getCurrentUser() === targetUsername) {
            globalState.setPermissions(permissions);
        }
    }
}

import { SupabaseClient } from './SupabaseClient.js';
import { InventoryService } from './InventoryService.js';

/**
 * DataService — CRUD operations against the relational Supabase schema.
 *
 * Maps front-end table IDs to the correct Supabase table and transforms
 * row data between the app format and the database column format.
 */
export class DataService {

    /**
     * Determine which Supabase table a front-end table ID maps to,
     * and supply additional defaults (e.g. the activity category).
     */
    static _resolveTable(tableId) {
        if (tableId === 'tbl_people' || tableId === 'people_table') {
            return { supaTable: 'people', category: null };
        }
        if (tableId === 'tbl_inventory') {
            return { supaTable: 'inventory', category: null };
        }
        if (tableId.startsWith('tbl_sport_')) {
            return { supaTable: 'sport_venues', category: tableId.replace('tbl_sport_', '') };
        }
        if (tableId.startsWith('tbl_activities_')) {
            return { supaTable: 'activities', category: tableId.replace('tbl_activities_', '') };
        }
        if (tableId === 'tbl_events') {
            return { supaTable: 'events', category: null };
        }
        if (tableId === 'tbl_ort') {
            return { supaTable: 'ort', category: null };
        }
        return { supaTable: tableId, category: null };
    }

    // ── READ ───────────────────────────────────────────────────

    /**
     * Load all rows for a front-end table.
     * Returns an array of plain objects.
     */
    static async loadRows(tableId) {
        const { supaTable, category } = this._resolveTable(tableId);

        let query = '?select=*';
        if (supaTable === 'people') {
            query = '?select=*,person_teams(teams(name))';
        } else if (supaTable === 'activities' && category) {
            query = `?select=*,activity_required_items(*,inventory(name))&category=eq.${category}`;
        } else if (supaTable === 'sport_venues') {
            query = '?select=*,address:ort(*)';
            if (category) query += `&sport_type=eq.${category}`;
        } else if (supaTable === 'events') {
            query = '?select=*,location:ort(*)';
        }

        const res = await SupabaseClient.get(supaTable, query);

        if (!res.ok) {
            const txt = await res.text();
            throw new Error(`Load failed for ${tableId}: ${res.status} ${txt}`);
        }

        const rows = await res.json();
        console.log(`[DataService] Data loaded for ${tableId || supaTable}:`, rows);
        return rows.map(r => this._fromDb(supaTable, r));
    }

    // ── SAVE (full table upsert) ──────────────────────────────

    /**
     * Save an entire table's rows. This upserts each row individually.
     * @param {string} tableId  Front-end table ID
     * @param {string} _filename  Legacy param (ignored)
     * @param {Array}  rows  Array of Row instances or plain objects
     */
    static async saveTable(tableId, _filename, rows) {
        const { supaTable, category } = this._resolveTable(tableId);

        if (supaTable === 'events') {
            await this._checkConflicts(rows);
        }

        const dbRows = rows.map(row => {
            const plain = row.toJSON ? row.toJSON() : row;
            return this._toDb(supaTable, plain, category);
        });

        // Delete rows that no longer exist (full replace strategy)
        await this._deleteRemovedRows(supaTable, category, dbRows);

        // Upsert all current rows
        if (dbRows.length > 0) {
            const res = await SupabaseClient.post(supaTable, dbRows, { 'Prefer': 'resolution=merge-duplicates' });

            if (!res.ok) {
                const txt = await res.text();
                console.error(`[DataService] Upsert failed for ${tableId}:`, txt);
                throw new Error(`Fehler beim Speichern: ${res.status}. Grund: ${txt}`);
            }

            // After successful save, sync junction tables
            for (let i = 0; i < rows.length; i++) {
                const plain = rows[i].toJSON ? rows[i].toJSON() : rows[i];
                const rowId = dbRows[i].id;
                if (!rowId) continue;

                if (supaTable === 'people' && plain.Team !== undefined) {
                    await this._syncPersonTeams(rowId, plain.Team);
                } else if (supaTable === 'activities' && plain.required_items !== undefined) {
                    await this._syncActivityInventory(rowId, plain.required_items);
                }
            }
        }

        await this.logAudit('UPSERT', supaTable, { affected: dbRows.length, category: category || 'none' });

        return { success: true, message: `Table ${tableId} saved` };
    }

    static async _checkConflicts(rows) {
        const userToTime = {};
        const conflicts = [];

        for (const row of rows) {
            const data = row.toJSON ? row.toJSON() : row;
            if (!data.date || !data.time || !data.games) continue;

            try {
                const games = JSON.parse(data.games);
                games.forEach(g => {
                    if (g.responsible) {
                        const key = `${data.date}_${data.time}`;
                        if (!userToTime[key]) userToTime[key] = [];
                        if (userToTime[key].includes(g.responsible)) {
                            conflicts.push(`Person ID ${g.responsible} ist mehrfach gebucht am ${data.date} um ${data.time} für ${g.name}`);
                        } else {
                            userToTime[key].push(g.responsible);
                        }
                    }
                });
            } catch(e) {}
        }

        if (conflicts.length > 0) {
            const { Dialog } = await import('../ui/Dialog.js');
            const ok = await Dialog.confirm({
                title: 'Konflikte erkannt',
                message: `Es gibt zeitliche Überschneidungen:\n\n${conflicts.join('\\n')}\n\nTrotzdem speichern?`,
                confirmText: 'Speichern erzwingen',
                confirmStyle: 'warning'
            });
            if (!ok) {
                throw new Error('Speichern durch Benutzer abgebrochen (Konflikt).');
            }
        }
    }

    static async logAudit(action, tableName, details) {
        try {
            const { GlobalStateManager } = await import('../core/GlobalStateManager.js');
            const user = GlobalStateManager.getInstance().getCurrentUser();
            const payload = {
                action,
                table_name: tableName,
                user_name: user,
                details: typeof details === 'string' ? details : JSON.stringify(details),
                created_at: new Date().toISOString()
            };
            const res = await SupabaseClient.post('audit_logs', [payload]);
            if (!res.ok) console.warn('[AuditService] Audit_logs table likely missing.');
        } catch(e) {
            console.warn('[AuditService] Skipping audit log:', e.message);
        }
    }

    /**
     * Delete rows from the DB that are no longer present in the current dataset.
     */
    static async _deleteRemovedRows(supaTable, category, dbRows) {
        const currentIds = dbRows.map(r => r.id).filter(Boolean);
        let deleteQuery;

        if (currentIds.length > 0) {
            deleteQuery = `?id=not.in.(${currentIds.map(id => `"${id}"`).join(',')})`;
        } else {
            deleteQuery = '?id=not.is.null';
        }

        if (supaTable === 'activities' && category) {
            deleteQuery += `&category=eq.${category}`;
        } else if (supaTable === 'sport_venues' && category) {
            deleteQuery += `&sport_type=eq.${category}`;
        }

        await SupabaseClient.delete(supaTable, deleteQuery);
    }

    // ── Column Mapping: App → DB ──────────────────────────────

    static _toDb(supaTable, row, category) {
        switch (supaTable) {
        case 'people':
            return {
                id: row.id,
                vorname: row.vorname || '',
                nachname: row.nachname || '',
                telefon: row['Tel.'] || row.telefon || '',
                status: (row.Status || row.status || 'Aktiv').toLowerCase(),
                rolle: this._capitalizeFirst(row.role || row.rolle || 'User'),
                responsibility_1: row.responsibility_1 ? row.responsibility_1.toLowerCase() : null,
                responsibility_2: row.responsibility_2 ? row.responsibility_2.toLowerCase() : null,
                spez_zustaendigkeit: row['Spez. Zuständigkeit'] || row.spez_zustaendigkeit || '',
                created_by: row.createdBy || null,
                created_at: row.createdAt || new Date().toISOString()
            };

        case 'activities':
            return {
                id: row.id,
                name: row.name || '',
                category,
                short_description: row.short_description || '',
                rules: row.rules || '',
                duration_minutes: this._parseIntOrNull(row.duration_minutes),
                preparation_minutes: this._parseIntOrNull(row.preparation_minutes),
                location: row.location || null,
                location_notes: row.location_notes || '',
                min_players: this._parseIntOrNull(row.min_players),
                max_players: this._parseIntOrNull(row.max_players),
                cost: row.cost || '',
                link: row.link || '',
                team_tasks: row.team_tasks || '',
                responsible_id: row.responsible || row.responsible_id || null,
                status: row.status || 'To Do',
                created_by: row.createdBy || null,
                created_at: row.createdAt || new Date().toISOString()
            };

        case 'inventory':
            return {
                id: row.id,
                name: row.name || '',
                quantity: row.quantity ? parseInt(row.quantity, 10) || 0 : 0,
                storage_location: row.storage_location || '',
                condition: row.condition || 'Gut',
                last_checked: row.last_checked || null,
                notes: row.notes || '',
                created_by: row.createdBy || null,
                created_at: row.createdAt || new Date().toISOString()
            };

        case 'sport_venues':
            return {
                id: row.id,
                sport_type: row.category || null,
                name: row.name || '',
                address: row.address?.id || null,
                phone: row.phone || '',
                venue_type: row.type || row.venue_type || null,
                indoor_outdoor: row.indoor_outdoor || null,
                cost: row.cost || '',
                notes: row.notes || '',
                created_by: row.createdBy || null,
                created_at: row.createdAt || new Date().toISOString()
            };

        case 'events':
            return {
                id: row.id,
                name: row.name || '',
                date: row.date || null,
                time: row.time || '18:30',
                location: row.location?.id || null,
                games: row.games || '',
                status: row.status || 'To Do',
                responsible_id: row.responsible || row.responsible_id || null,
                notes: row.notes || '',
                created_by: row.createdBy || null,
                created_at: row.createdAt || new Date().toISOString()
            };

        case 'ort':
            return {
                id: row.id,
                title: row.title || '',
                street: row.street || '',
                address_extra: row.address_extra || '',
                zip_code: row.zip_code || '',
                city: row.city || '',
                link: row.link || '',
                notes: row.notes || '',
                created_by: row.createdBy || null,
                created_at: row.createdAt || new Date().toISOString()
            };

        default:
            return row;
        }
    }

    // ── Column Mapping: DB → App ──────────────────────────────

    static _fromDb(supaTable, row) {
        switch (supaTable) {
        case 'people':
            return {
                id: row.id,
                vorname: row.vorname || '',
                nachname: row.nachname || '',
                'Tel.': row.telefon || '',
                Status: row.status ? this._capitalizeFirst(row.status) : 'Aktiv',
                role: row.rolle || 'User',
                responsibility_1: row.responsibility_1 ? this._capitalizeFirst(row.responsibility_1) : '',
                responsibility_2: row.responsibility_2 ? this._capitalizeFirst(row.responsibility_2) : '',
                'Spez. Zuständigkeit': row.spez_zustaendigkeit || '',
                Team: (row.person_teams || []).map(pt => pt.teams?.name).filter(Boolean).join(', '),
                createdBy: row.created_by || 'Unbekannt',
                createdAt: row.created_at || null,
            };

        case 'activities':
            return {
                id: row.id,
                name: row.name || '',
                required_items: (row.activity_required_items || [])
                    .map(ari => ari.quantity_needed ? `${ari.inventory?.name} (${ari.quantity_needed})` : ari.inventory?.name)
                    .filter(Boolean)
                    .join(', '),
                short_description: row.short_description || '',
                rules: row.rules || '',
                duration_minutes: row.duration_minutes ?? '',
                preparation_minutes: row.preparation_minutes ?? '',
                location: row.location || '',
                location_notes: row.location_notes || '',
                min_players: row.min_players ?? '',
                max_players: row.max_players ?? '',
                cost: row.cost || '',
                link: row.link || '',
                team_tasks: row.team_tasks || '',
                responsible: row.responsible_id || '',
                status: row.status || 'To Do',
                createdBy: row.created_by || 'Unbekannt',
                createdAt: row.created_at || null,
            };

        case 'inventory':
            return {
                id: row.id,
                name: row.name || '',
                quantity: row.quantity ?? '',
                storage_location: row.storage_location || '',
                condition: row.condition || 'gut',
                last_checked: row.last_checked || '',
                notes: row.notes || '',
                createdBy: row.created_by || 'Unbekannt',
                createdAt: row.created_at || null,
            };

        case 'sport_venues':
            return {
                id: row.id,
                name: row.name || '',
                address: row.address || '',
                phone: row.phone || '',
                type: row.venue_type || '',
                indoor_outdoor: row.indoor_outdoor || '',
                cost: row.cost || '',
                notes: row.notes || '',
                createdBy: row.created_by || 'Unbekannt',
                createdAt: row.created_at || null,
            };

        case 'events':
            return {
                id: row.id,
                name: row.name || '',
                date: row.date || '',
                time: row.time || '',
                location: row.location || '',
                games: row.games || '',
                status: row.status || 'To Do',
                responsible: row.responsible_id || '',
                notes: row.notes || '',
                createdBy: row.created_by || 'Unbekannt',
                createdAt: row.created_at || null,
            };

        case 'ort':
            return {
                id: row.id,
                title: row.title || '',
                street: row.street || '',
                address_extra: row.address_extra || '',
                zip_code: row.zip_code || '',
                city: row.city || '',
                link: row.link || '',
                notes: row.notes || '',
                createdBy: row.created_by || 'Unbekannt',
                createdAt: row.created_at || null,
            };

        default:
            return row;
        }
    }

    // ── People-specific helpers ───────────────────────────────

    static async loadPeople() {
        return this.loadRows('tbl_people');
    }

    static async savePeople(rows) {
        return this.saveTable('tbl_people', null, rows);
    }

    // ── Junction Sync Helpers ────────────────────────────────

    static async _syncPersonTeams(personId, teamString) {
        await SupabaseClient.delete('person_teams', `?person_id=eq.${personId}`);

        if (!teamString || teamString === '—') return;

        const teamNames = teamString.split(',').map(s => s.trim()).filter(Boolean);
        if (teamNames.length === 0) return;

        const teamsRes = await SupabaseClient.get(
            'teams',
            `?name=in.(${teamNames.map(n => `"${n}"`).join(',')})`
        );
        if (!teamsRes.ok) return;
        const teams = await teamsRes.json();

        const junctionRows = teams.map(t => ({
            person_id: personId,
            team_id: t.id
        }));

        if (junctionRows.length > 0) {
            const res = await SupabaseClient.post('person_teams', junctionRows);
            if (!res.ok) console.error('[DataService] Sync PersonTeams failed:', await res.text());
        }
    }

    static async _syncActivityInventory(activityId, inventoryString) {
        await SupabaseClient.delete('activity_required_items', `?activity_id=eq.${activityId}`);

        const items = InventoryService.parseInventoryString(inventoryString);
        if (items.length === 0) return;

        const names = items.map(i => i.name);
        const invRes = await SupabaseClient.get(
            'inventory',
            `?name=in.(${names.map(n => `"${n}"`).join(',')})`
        );
        if (!invRes.ok) {
            console.error('[DataService] Sync Inventory fetch failed:', await invRes.text());
            return;
        }
        const inventory = await invRes.json();

        const junctionRows = items.map(item => {
            const match = inventory.find(inv => inv.name.toLowerCase() === item.name.toLowerCase());
            if (!match) return null;
            return {
                activity_id: activityId,
                inventory_id: match.id,
                quantity_needed: item.quantity ? parseInt(item.quantity, 10) || 0 : 0,
            };
        }).filter(Boolean);

        if (junctionRows.length > 0) {
            const res = await SupabaseClient.post('activity_required_items', junctionRows);
            if (!res.ok) console.error('[DataService] Sync ActivityInventory failed:', await res.text());
        }
    }

    static async createActivity(name, category = 'sonstige') {
        const payload = {
            name,
            category,
            status: 'To Do',
            created_at: new Date().toISOString()
        };
        const res = await SupabaseClient.post('activities', payload, { 'Prefer': 'return=representation' });
        if (!res.ok) {
            const txt = await res.text();
            throw new Error(`Failed to create activity: ${txt}`);
        }
        const rows = await res.json();
        return rows[0];
    }

    // ── Utility ───────────────────────────────────────────────

    static _capitalizeFirst(str) {
        if (!str) return '';
        return str.charAt(0).toUpperCase() + str.slice(1).toLowerCase();
    }

    static _parseIntOrNull(value) {
        if (!value) return null;
        const parsed = parseInt(value, 10);
        return isNaN(parsed) ? null : parsed;
    }
}

import { SupabaseClient } from './SupabaseClient.js';
import { InventoryService } from './InventoryService.js';

/**
 * DataService — CRUD operations against the relational Supabase schema.
 *
 * Maps front-end table IDs to the correct Supabase table and transforms
 * row data between the app format and the database column format.
 */
export class DataService {

    /**
     * Determine which Supabase table a front-end table ID maps to,
     * and supply additional defaults (e.g. the activity category).
     */
    static _resolveTable(tableId) {
        if (tableId === 'tbl_people' || tableId === 'people_table') {
            return { supaTable: 'people', category: null };
        }
        if (tableId === 'tbl_inventory') {
            return { supaTable: 'inventory', category: null };
        }
        if (tableId.startsWith('tbl_sport_')) {
            return { supaTable: 'sport_venues', category: tableId.replace('tbl_sport_', '') };
        }
        if (tableId.startsWith('tbl_activities_')) {
            return { supaTable: 'activities', category: tableId.replace('tbl_activities_', '') };
        }
        if (tableId === 'tbl_events') {
            return { supaTable: 'events', category: null };
        }
        if (tableId === 'tbl_ort') {
            return { supaTable: 'ort', category: null };
        }
        return { supaTable: tableId, category: null };
    }

    // ── READ ───────────────────────────────────────────────────

    /**
     * Load all rows for a front-end table.
     * Returns an array of plain objects.
     */
    static async loadRows(tableId) {
        const { supaTable, category } = this._resolveTable(tableId);

        let query = '?select=*';
        if (supaTable === 'people') {
            query = '?select=*,person_teams(teams(name))';
        } else if (supaTable === 'activities' && category) {
            query = `?select=*,activity_required_items(*,inventory(name))&category=eq.${category}`;
        } else if (supaTable === 'sport_venues') {
            query = '?select=*,address:ort(*)';
            if (category) query += `&sport_type=eq.${category}`;
        } else if (supaTable === 'events') {
            query = '?select=*,location:ort(*)';
        }

        const res = await SupabaseClient.get(supaTable, query);

        if (!res.ok) {
            const txt = await res.text();
            throw new Error(`Load failed for ${tableId}: ${res.status} ${txt}`);
        }

        const rows = await res.json();
        console.log(`[DataService] Data loaded for ${tableId || supaTable}:`, rows);
        return rows.map(r => this._fromDb(supaTable, r));
    }

    // ── SAVE (full table upsert) ──────────────────────────────

    /**
     * Save an entire table's rows. This upserts each row individually.
     * @param {string} tableId  Front-end table ID
     * @param {string} _filename  Legacy param (ignored)
     * @param {Array}  rows  Array of Row instances or plain objects
     */
    static async saveTable(tableId, _filename, rows) {
        const { supaTable, category } = this._resolveTable(tableId);

        if (supaTable === 'events') {
            await this._checkConflicts(rows);
        }

        // Check for concurrent edits
        await this._checkConcurrentEdits(tableId, rows);

        const dbRows = rows.map(row => {
            const plain = row.toJSON ? row.toJSON() : row;
            return this._toDb(supaTable, plain, category);
        });

        // Delete rows that no longer exist (full replace strategy)
        await this._deleteRemovedRows(supaTable, category, dbRows);

        // Upsert all current rows
        if (dbRows.length > 0) {
            const res = await SupabaseClient.post(supaTable, dbRows, { 'Prefer': 'resolution=merge-duplicates' });

            if (!res.ok) {
                const txt = await res.text();
                console.error(`[DataService] Upsert failed for ${tableId}:`, txt);
                throw new Error(`Fehler beim Speichern: ${res.status}. Grund: ${txt}`);
            }

            // After successful save, sync junction tables
            for (let i = 0; i < rows.length; i++) {
                const plain = rows[i].toJSON ? rows[i].toJSON() : rows[i];
                const rowId = dbRows[i].id;
                if (!rowId) continue;

                if (supaTable === 'people' && plain.Team !== undefined) {
                    await this._syncPersonTeams(rowId, plain.Team);
                } else if (supaTable === 'activities' && plain.required_items !== undefined) {
                    await this._syncActivityInventory(rowId, plain.required_items);
                }
            }
        }

        await this.logAudit('UPSERT', supaTable, { affected: dbRows.length, category: category || 'none' });

        return { success: true, message: `Table ${tableId} saved` };
    }

    static async _checkConflicts(rows) {
        const userToTime = {};
        const conflicts = [];

        for (const row of rows) {
            const data = row.toJSON ? row.toJSON() : row;
            if (!data.date || !data.time || !data.games) continue;

            try {
                const games = JSON.parse(data.games);
                games.forEach(g => {
                    if (g.responsible) {
                        const key = `${data.date}_${data.time}`;
                        if (!userToTime[key]) userToTime[key] = [];
                        if (userToTime[key].includes(g.responsible)) {
                            conflicts.push(`Person ID ${g.responsible} ist mehrfach gebucht am ${data.date} um ${data.time} für ${g.name}`);
                        } else {
                            userToTime[key].push(g.responsible);
                        }
                    }
                });
            } catch(e) {}
        }

        if (conflicts.length > 0) {
            const { Dialog } = await import('../ui/Dialog.js');
            const ok = await Dialog.confirm({
                title: 'Konflikte erkannt',
                message: `Es gibt zeitliche Überschneidungen:\n\n${conflicts.join('\\n')}\n\nTrotzdem speichern?`,
                confirmText: 'Speichern erzwingen',
                confirmStyle: 'warning'
            });
            if (!ok) {
                throw new Error('Speichern durch Benutzer abgebrochen (Konflikt).');
            }
        }
    }

    static async logAudit(action, tableName, details) {
        try {
            const { GlobalStateManager } = await import('../core/GlobalStateManager.js');
            const user = GlobalStateManager.getInstance().getCurrentUser();
            const payload = {
                action,
                table_name: tableName,
                user_name: user,
                details: typeof details === 'string' ? details : JSON.stringify(details),
                created_at: new Date().toISOString()
            };
            const res = await SupabaseClient.post('audit_logs', [payload]);
            if (!res.ok) console.warn('[AuditService] Audit_logs table likely missing.');
        } catch(e) {
            console.warn('[AuditService] Skipping audit log:', e.message);
        }
    }

    /**
     * Delete rows from the DB that are no longer present in the current dataset.
     */
    static async _deleteRemovedRows(supaTable, category, dbRows) {
        const currentIds = dbRows.map(r => r.id).filter(Boolean);
        let deleteQuery;

        if (currentIds.length > 0) {
            deleteQuery = `?id=not.in.(${currentIds.map(id => `"${id}"`).join(',')})`;
        } else {
            deleteQuery = '?id=not.is.null';
        }

        if (supaTable === 'activities' && category) {
            deleteQuery += `&category=eq.${category}`;
        } else if (supaTable === 'sport_venues' && category) {
            deleteQuery += `&sport_type=eq.${category}`;
        }

        await SupabaseClient.delete(supaTable, deleteQuery);
    }

    // ── Column Mapping: App → DB ──────────────────────────────

    static _toDb(supaTable, row, category) {
        switch (supaTable) {
        case 'people':
            return {
                id: row.id,
                vorname: row.vorname || '',
                nachname: row.nachname || '',
                telefon: row['Tel.'] || row.telefon || '',
                status: (row.Status || row.status || 'Aktiv').toLowerCase(),
                rolle: this._capitalizeFirst(row.role || row.rolle || 'User'),
                responsibility_1: row.responsibility_1 ? row.responsibility_1.toLowerCase() : null,
                responsibility_2: row.responsibility_2 ? row.responsibility_2.toLowerCase() : null,
                spez_zustaendigkeit: row['Spez. Zuständigkeit'] || row.spez_zustaendigkeit || '',
                created_by: row.createdBy || null,
                created_at: row.createdAt || new Date().toISOString()
            };

        case 'activities':
            return {
                id: row.id,
                name: row.name || '',
                category,
                short_description: row.short_description || '',
                rules: row.rules || '',
                duration_minutes: this._parseIntOrNull(row.duration_minutes),
                preparation_minutes: this._parseIntOrNull(row.preparation_minutes),
                location: row.location || null,
                location_notes: row.location_notes || '',
                min_players: this._parseIntOrNull(row.min_players),
                max_players: this._parseIntOrNull(row.max_players),
                cost: row.cost || '',
                link: row.link || '',
                team_tasks: row.team_tasks || '',
                responsible_id: row.responsible || row.responsible_id || null,
                status: row.status || 'To Do',
                created_by: row.createdBy || null,
                created_at: row.createdAt || new Date().toISOString()
            };

        case 'inventory':
            return {
                id: row.id,
                name: row.name || '',
                quantity: row.quantity ? parseInt(row.quantity, 10) || 0 : 0,
                storage_location: row.storage_location || '',
                condition: row.condition || 'Gut',
                last_checked: row.last_checked || null,
                notes: row.notes || '',
                created_by: row.createdBy || null,
                created_at: row.createdAt || new Date().toISOString()
            };

        case 'sport_venues':
            return {
                id: row.id,
                sport_type: row.category || null,
                name: row.name || '',
                address: row.address?.id || null,
                phone: row.phone || '',
                venue_type: row.type || row.venue_type || null,
                indoor_outdoor: row.indoor_outdoor || null,
                cost: row.cost || '',
                notes: row.notes || '',
                created_by: row.createdBy || null,
                created_at: row.createdAt || new Date().toISOString()
            };

        case 'events':
            return {
                id: row.id,
                name: row.name || '',
                date: row.date || null,
                time: row.time || '18:30',
                location: row.location?.id || null,
                games: row.games || '',
                status: row.status || 'To Do',
                responsible_id: row.responsible || row.responsible_id || null,
                notes: row.notes || '',
                created_by: row.createdBy || null,
                created_at: row.createdAt || new Date().toISOString()
            };

        case 'ort':
            return {
                id: row.id,
                title: row.title || '',
                street: row.street || '',
                address_extra: row.address_extra || '',
                zip_code: row.zip_code || '',
                city: row.city || '',
                link: row.link || '',
                notes: row.notes || '',
                created_by: row.createdBy || null,
                created_at: row.createdAt || new Date().toISOString()
            };

        default:
            return row;
        }
    }

    // ── Column Mapping: DB → App ──────────────────────────────

    static _fromDb(supaTable, row) {
        switch (supaTable) {
        case 'people':
            return {
                id: row.id,
                vorname: row.vorname || '',
                nachname: row.nachname || '',
                'Tel.': row.telefon || '',
                Status: row.status ? this._capitalizeFirst(row.status) : 'Aktiv',
                role: row.rolle || 'User',
                responsibility_1: row.responsibility_1 ? this._capitalizeFirst(row.responsibility_1) : '',
                responsibility_2: row.responsibility_2 ? this._capitalizeFirst(row.responsibility_2) : '',
                'Spez. Zuständigkeit': row.spez_zustaendigkeit || '',
                Team: (row.person_teams || []).map(pt => pt.teams?.name).filter(Boolean).join(', '),
                createdBy: row.created_by || 'Unbekannt',
                createdAt: row.created_at || null,
