            };

        case 'sport_venues':
            return {
                id: row.id,
                name: row.name || '',
                address: row.address || '',
                phone: row.phone || '',
                type: row.venue_type || '',
                indoor_outdoor: row.indoor_outdoor || '',
                cost: row.cost || '',
                notes: row.notes || '',
                createdBy: row.created_by || 'Unbekannt',
                createdAt: row.created_at || null,
                last_updated: row.updated_at || null,
            };

        case 'events':
            return {
                id: row.id,
                name: row.name || '',
                date: row.date || '',
                time: row.time || '',
                location: row.location || '',
                games: row.games || '',
                status: row.status || 'To Do',
                responsible: row.responsible_id || '',
                notes: row.notes || '',
                createdBy: row.created_by || 'Unbekannt',
                createdAt: row.created_at || null,
                last_updated: row.updated_at || null,
            };

        case 'ort':
            return {
                id: row.id,
                title: row.title || '',
                street: row.street || '',
                address_extra: row.address_extra || '',
                zip_code: row.zip_code || '',
                city: row.city || '',
                link: row.link || '',
