        max-width: 95vw;
        padding: 16px;
    }

    .custom-dialog .save-btn-header,
    .custom-dialog .discard-btn-header {
        min-height: 44px;
    }
}

.filter-bar {
    background: var(--bg-secondary);
    border-bottom: 1px solid var(--border-light);
    padding: 12px 24px;
    height: auto;
    max-height: 800px; /* High enough for many wrapped filter rows */
    min-height: 48px;
    transition: max-height 0.4s ease, opacity 0.3s ease, padding 0.3s ease;
    z-index: 80; /* Higher than table top */
    position: relative;
    overflow: visible;
}


.filter-bar.hidden {
    max-height: 0;
    min-height: 0;
    padding-top: 0;
    padding-bottom: 0;
    border-bottom-width: 0;
    opacity: 0;
    pointer-events: none;
    overflow: hidden;
}

.filter-bar-content {
    display: flex;
    align-items: center;
    gap: 24px;
    width: 100%;
    flex-wrap: wrap;
    padding: 4px 0;
}

.filter-group {
    display: flex;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
}

.filter-row {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}

.filter-label {
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--text-muted);
    white-space: nowrap;
}

.filter-separator {
    width: 1px;
    height: 24px;
    background: var(--border-light);
    margin: 0 8px;
}

/* Dropdown refinements for filter bar context */
.filter-bar .dropdown-container {
    min-width: 160px;
}

.filter-bar .nav-btn.dropdown-btn {
    background: var(--bg);
    border: 1px solid var(--border);
    justify-content: space-between;
    width: 100%;
    font-size: 12px;
    padding: 4px 12px;
}

.filter-bar .dropdown-menu {
    min-width: 200px;
    z-index: 10000; /* Very high */
    max-height: 300px; /* Prevent it from being TOO long */
    overflow-y: auto;
}


.filter-bar .filter-input {
    padding: 4px 12px;
    border: 1px solid var(--border);
    border-radius: var(--radius-sm);
    background: var(--bg);
    color: var(--text-primary);
    font-size: 12px;
    width: 150px;
    outline: none;
    transition: all var(--transition);
}

.filter-bar .filter-input:focus {
    border-color: var(--accent);
    box-shadow: 0 0 0 2px var(--accent-light);
}

.filter-add-btn, .filter-remove-btn {
    background: var(--bg);
    border: 1px solid var(--border);
    border-radius: var(--radius-sm);
    width: 24px;
    height: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    color: var(--text-secondary);
    font-size: 14px;
    font-weight: 500;
    transition: all var(--transition);
    padding: 0;
    flex-shrink: 0;
}

.filter-add-btn:hover {
    background: var(--accent-light);
    color: var(--accent);
    border-color: var(--accent);
}

.filter-remove-btn:hover {
    background: var(--error-light);
    color: var(--error);
    border-color: var(--error);
}

.filter-clear-all-btn {
    margin-left: auto;
    background: transparent;
    border: 1px solid var(--border);
    color: var(--text-muted);
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
    padding: 6px 12px;
    border-radius: var(--radius-sm);
    cursor: pointer;
    transition: all var(--transition);
}

.filter-clear-all-btn:hover {
    background: var(--bg-tertiary);
    color: var(--text-primary);
    border-color: var(--text-muted);
}

/* Multi-select styling */
.dropdown-item.selected {
    background: var(--accent-light) !important;
    color: var(--accent) !important;
    font-weight: 600;
}

.dropdown-btn.active {
    border-color: var(--accent) !important;
    background: var(--accent-light) !important;
    color: var(--accent) !important;
}

.dropdown-btn.active span {
    color: var(--accent) !important;
}

.dropdown-item.styled-status-item {
    margin: 4px 8px !important;
    border-radius: var(--radius-sm) !important;
    padding: 6px 12px !important;
    font-weight: 600 !important;
    border: 1px solid rgba(0,0,0,0.05) !important;
    width: auto !important;
    display: block !important;
    text-align: center !important;
}

.dropdown-item.styled-status-item:hover {
    filter: brightness(0.95);
}

