    align-items: stretch;
}

.split-btn-group {
    background: var(--bg);
}

.split-main-btn {
    border-top-right-radius: 0 !important;
    border-bottom-right-radius: 0 !important;
    padding-right: 12px;
}

.split-divider {
    width: 2px;
