}

.login-option:hover {
    background: var(--bg-hover);
}

.option-name {
    font-size: 0.9rem;
    color: var(--text-primary);
}

.option-name {
    font-size: 0.9rem;
    color: var(--text-primary);
}

.option-role {
    font-size: 0.75rem;
    color: var(--text-muted);
    font-weight: 500;
}

