/* ── Notion-inspired Color Tokens ──────────────────── */
:root {
    /* Grays - Notion uses subtle, balanced grays */
    --bg:             #ffffff;
    --bg-secondary:   #f9f9f8;
    --bg-tertiary:    #f0f0ee;
    --bg-hover:       #ececeb;
    --border:         #e5e5e3;
    --border-light:   #efefed;

    /* Text colors - Notion prioritizes readability */
    --text-primary:   #37352f;
    --text-secondary: #626060;
    --text-muted:     #9c9a96;

    /* Semantic colors - More muted and sophisticated */
    --accent:         #0084ff;
    --accent-light:   #f0f6ff;
    --accent-hover:   #0071d9;
    --success:        #34a853;
    --success-light:  #f0f7f0;
    --error:          #d20f0f;
    --error-light:    #fdf1f1;
    --warning:        #f59e0b;
    --warning-light:  #fffbf0;

    /* Shadows - Notion's soft, minimal shadows */
    --shadow-xs:      0 1px 2px rgba(15,15,11,0.04);
    --shadow-sm:      0 2px 4px rgba(15,15,11,0.06);
    --shadow-md:      0 4px 8px rgba(15,15,11,0.08);
    --shadow-lg:      0 8px 16px rgba(15,15,11,0.1);

    /* RGB variants for transparency */
    --accent-rgb:     0, 132, 255;
    --border-color-rgb: 229, 229, 227;

    /* Spacing & Radius */
    --radius:         6px;
    --radius-sm:      4px;
    --transition:     0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

[data-theme="dark"] {
    /* Dark mode - Notion's dark theme is true dark, not gray */
    --bg:             #1a1a1a;
    --bg-secondary:   #242424;
    --bg-tertiary:    #2e2e2e;
    --bg-hover:       #353535;
    --border:         #373737;
    --border-light:   #404040;

    --text-primary:   #ebebeb;
    --text-secondary: #b3b3b1;
    --text-muted:     #65645f;

    --accent:         #3291ff;
    --accent-light:   #0d1a2e;
    --accent-hover:   #0071d9;
    --success:        #34a853;
    --success-light:  #1e3a1f;
    --error:          #ff4757;
    --error-light:    #3a1a1a;
    --warning:        #ffb700;
    --warning-light:  #3a2f1a;

    --shadow-xs:      0 1px 2px rgba(0,0,0,0.2);
    --shadow-sm:      0 2px 4px rgba(0,0,0,0.3);
    --shadow-md:      0 4px 8px rgba(0,0,0,0.4);
    --shadow-lg:      0 8px 16px rgba(0,0,0,0.5);

    --accent-rgb:     50, 145, 255;
    --border-color-rgb: 55, 55, 55;
}

/* ── Reset ───────────────────────────────────────────── */
*, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

html, body {
    height: 100%;
    background: var(--bg);
    color: var(--text-primary);
