import '../styles/Dialog.css';
import { BaseDialog } from './BaseDialog.js';

export class Dialog {
    static async confirm({ message, confirmText = 'Bestätigen', confirmStyle = 'warning' }) {
        return BaseDialog.show({
            onEscapeValue: false,
            render: (dialog, overlay, resolve, cleanup) => {
                const msgSpan = document.createElement('span');
                msgSpan.className = 'unsaved-msg';
                msgSpan.textContent = message;

                const confirmBtn = document.createElement('button');
                confirmBtn.className = confirmStyle === 'warning' ? 'discard-btn-header' : 'save-btn-header';
                confirmBtn.textContent = confirmText;

                const cancelBtn = document.createElement('button');
                cancelBtn.className = confirmStyle === 'warning' ? 'save-btn-header' : 'discard-btn-header';
                cancelBtn.textContent = 'Abbrechen';

                confirmBtn.addEventListener('click', () => resolve(true));
                cancelBtn.addEventListener('click', () => resolve(false));

                dialog.appendChild(msgSpan);
                dialog.appendChild(cancelBtn);
                dialog.appendChild(confirmBtn);

                if (confirmStyle === 'warning') {
                    cancelBtn.focus();
                } else {
                    confirmBtn.focus();
                }
            },
            onKeydown: (e, dialog, overlay, resolve) => {
                if (e.key === 'Enter') resolve(true);
            }
        });
    }

    static async prompt({ message, confirmText = 'Speichern', type = 'text', placeholder = '' }) {
        return BaseDialog.show({
            dialogClassName: 'custom-dialog prompt-dialog',
            onEscapeValue: null,
            render: (dialog, overlay, resolve, cleanup) => {
                const msgSpan = document.createElement('div');
                msgSpan.className = 'unsaved-msg';
                msgSpan.textContent = message;
                msgSpan.style.marginBottom = '12px';

                const input = document.createElement('input');
                input.type = type;
                input.placeholder = placeholder;
                input.className = 'dialog-input';
                input.style.display = 'block';
                input.style.width = '100%';
                input.style.marginBottom = '16px';

                const confirmBtn = document.createElement('button');
                confirmBtn.className = 'save-btn-header';
                confirmBtn.textContent = confirmText;

                const cancelBtn = document.createElement('button');
                cancelBtn.className = 'discard-btn-header';
                cancelBtn.textContent = 'Abbrechen';

                confirmBtn.addEventListener('click', () => resolve(input.value));
                cancelBtn.addEventListener('click', () => resolve(null));

                dialog.appendChild(msgSpan);
                dialog.appendChild(input);
                dialog.appendChild(cancelBtn);
                dialog.appendChild(confirmBtn);

                setTimeout(() => input.focus(), 50);
            },
            onKeydown: (e, dialog, overlay, resolve) => {
                if (e.key === 'Enter') resolve(dialog.querySelector('input').value);
            }
        });
    }

    static async alert({ message, title = 'Info' }) {
        return BaseDialog.show({
            onEscapeValue: undefined,
            render: (dialog, overlay, resolve, cleanup) => {
                const titleEl = document.createElement('div');
                titleEl.className = 'unsaved-msg';
                titleEl.style.fontWeight = '700';
                titleEl.style.marginBottom = '8px';
                titleEl.textContent = title;

                const msgSpan = document.createElement('div');
                msgSpan.className = 'unsaved-msg';
                msgSpan.innerHTML = message.replace(/\n/g, '<br>');
                msgSpan.style.marginBottom = '16px';
                msgSpan.style.fontSize = '13px';
                msgSpan.style.lineHeight = '1.5';

                const okBtn = document.createElement('button');
                okBtn.className = 'save-btn-header';
                okBtn.textContent = 'OK';
                okBtn.style.margin = '0 auto';
                okBtn.style.display = 'block';

                okBtn.addEventListener('click', () => resolve());

                dialog.appendChild(titleEl);
                dialog.appendChild(msgSpan);
                dialog.appendChild(okBtn);

                okBtn.focus();
            },
            onKeydown: (e, dialog, overlay, resolve) => {
                if (e.key === 'Enter') resolve();
            }
        });
    }

    static async showAddColumnDialog(tableId, availableEnums = []) {
        return BaseDialog.show({
            onEscapeValue: null,
            render: (dialog, overlay, resolve, cleanup) => {
                overlay.style.zIndex = '10000';

                dialog.style.flexDirection = 'column';
                dialog.style.width = '460px'; // Slightly wider for row layout
                dialog.style.alignItems = 'stretch';
                dialog.style.gap = '16px';

                const title = document.createElement('div');
                title.className = 'unsaved-msg';
                title.style.fontWeight = '700';
                title.style.marginBottom = '8px';
                title.textContent = 'Neue Spalte hinzufügen';
                dialog.appendChild(title);

                const createRow = (labelText, inputEl) => {
                    const row = document.createElement('div');
                    row.style.display = 'flex';
                    row.style.alignItems = 'center';
                    row.style.justifyContent = 'space-between';
                    row.style.gap = '16px';

                    const lbl = document.createElement('div');
                    lbl.className = 'unsaved-msg';
                    lbl.style.fontSize = '13px';
                    lbl.style.whiteSpace = 'nowrap';
                    lbl.textContent = labelText;

                    inputEl.style.width = '240px';
                    inputEl.style.marginBottom = '0'; // Override previous default

                    row.appendChild(lbl);
                    row.appendChild(inputEl);
                    return row;
                };

                // Name
                const nameInput = document.createElement('input');
                nameInput.className = 'dialog-input';
                dialog.appendChild(createRow('Name der Spalte:', nameInput));

                // Type
                const typeSelect = document.createElement('select');
                typeSelect.className = 'dialog-input';
                ['text', 'int', 'number', 'date', 'time', 'boolean', 'enum'].forEach(t => {
                    const opt = document.createElement('option');
                    opt.value = t;
                    opt.textContent = t;
                    typeSelect.appendChild(opt);
                });
                dialog.appendChild(createRow('Datentyp:', typeSelect));

                // --- Enum Section ---
                const enumSelectionRowWrap = document.createElement('div');
                enumSelectionRowWrap.style.display = 'none';
                const enumSelect = document.createElement('select');
                enumSelect.className = 'dialog-input';

                const populateEnums = () => {
                    enumSelect.innerHTML = '';
                    const baseOpt = document.createElement('option');
                    baseOpt.value = '';
                    baseOpt.textContent = '-- Bestehenden Enum wählen --';
                    enumSelect.appendChild(baseOpt);

                    availableEnums.forEach(e => {
                        const opt = document.createElement('option');
                        opt.value = e;
                        opt.textContent = e;
                        enumSelect.appendChild(opt);
                    });

                    const newOpt = document.createElement('option');
                    newOpt.value = 'CREATE_NEW';
                    newOpt.textContent = '+ Neuen Enum erstellen...';
                    enumSelect.appendChild(newOpt);
                };
                populateEnums();
                enumSelectionRowWrap.appendChild(createRow('Welcher Enum?', enumSelect));
                dialog.appendChild(enumSelectionRowWrap);

                // New Enum Creation Section (Hidden initially)
                const newEnumInputs = document.createElement('div');
                newEnumInputs.style.display = 'none';
                newEnumInputs.style.flexDirection = 'column';
                newEnumInputs.style.gap = '12px';
                newEnumInputs.style.padding = '12px';
                newEnumInputs.style.background = 'var(--bg-secondary)';
                newEnumInputs.style.borderRadius = 'var(--radius-sm)';
                newEnumInputs.style.marginTop = '4px';

                const newEnumNameInput = document.createElement('input');
                newEnumNameInput.className = 'dialog-input';
                newEnumNameInput.placeholder = 'z.B. parkplatz_enum';
                newEnumInputs.appendChild(createRow('Enum-Name (DB):', newEnumNameInput));

                const newEnumOptionsInput = document.createElement('input');
                newEnumOptionsInput.className = 'dialog-input';
                newEnumOptionsInput.placeholder = 'Option A, Option B, ...';
                newEnumInputs.appendChild(createRow('Optionen:', newEnumOptionsInput));
                dialog.appendChild(newEnumInputs);

                typeSelect.onchange = () => {
                    const isEnum = typeSelect.value === 'enum';
                    enumSelectionRowWrap.style.display = isEnum ? 'block' : 'none';
                    if (!isEnum) newEnumInputs.style.display = 'none';
                };

                enumSelect.onchange = () => {
                    newEnumInputs.style.display = enumSelect.value === 'CREATE_NEW' ? 'flex' : 'none';
                };

                const actions = document.createElement('div');
                actions.style.display = 'flex';
                actions.style.justifyContent = 'flex-end';
                actions.style.gap = '12px';
                actions.style.marginTop = '8px';

                const cancelBtn = document.createElement('button');
                cancelBtn.className = 'discard-btn-header';
                cancelBtn.textContent = 'Abbrechen';

                const confirmBtn = document.createElement('button');
                confirmBtn.className = 'save-btn-header';
                confirmBtn.textContent = 'Hinzufügen';

                cancelBtn.onclick = () => { resolve(null); };
                confirmBtn.onclick = () => {
                    const nameValue = nameInput.value.trim();
                    const typeValue = typeSelect.value;
                    if (!nameValue) return; // Flash handled by caller or simple return

                    let result = { name: nameValue, type: typeValue };

                    if (typeValue === 'enum') {
                        if (enumSelect.value === 'CREATE_NEW') {
                            const newName = newEnumNameInput.value.trim();
                            const options = newEnumOptionsInput.value.split(',').map(o => o.trim()).filter(o => o);
                            if (!newName || options.length === 0) return alert('Name und Optionen für neuen Enum erforderlich');
                            result.newEnum = { name: newName, options };
                            result.type = newName;
                        } else if (enumSelect.value) {
                            result.type = enumSelect.value;
                        } else {
                            return alert('Bitte einen Enum wählen');
                        }
                    }

                    resolve(result);
                };

                actions.appendChild(cancelBtn);
                actions.appendChild(confirmBtn);
                dialog.appendChild(actions);

                setTimeout(() => nameInput.focus(), 50);
            }
        });
    }
}

import '../styles/Dialog.css';
import { BaseDialog } from './BaseDialog.js';

export class Dialog {
    static async confirm({ message, confirmText = 'Bestätigen', confirmStyle = 'warning' }) {
        return BaseDialog.show({
            onEscapeValue: false,
            render: (dialog, overlay, resolve, cleanup) => {
                const msgSpan = document.createElement('span');
                msgSpan.className = 'unsaved-msg';
                msgSpan.textContent = message;

                const confirmBtn = document.createElement('button');
                confirmBtn.className = confirmStyle === 'warning' ? 'discard-btn-header' : 'save-btn-header';
                confirmBtn.textContent = confirmText;

                const cancelBtn = document.createElement('button');
                cancelBtn.className = confirmStyle === 'warning' ? 'save-btn-header' : 'discard-btn-header';
                cancelBtn.textContent = 'Abbrechen';

                confirmBtn.addEventListener('click', () => resolve(true));
                cancelBtn.addEventListener('click', () => resolve(false));

                dialog.appendChild(msgSpan);
                dialog.appendChild(cancelBtn);
                dialog.appendChild(confirmBtn);

                if (confirmStyle === 'warning') {
                    cancelBtn.focus();
                } else {
                    confirmBtn.focus();
                }
            },
            onKeydown: (e, dialog, overlay, resolve) => {
                if (e.key === 'Enter') resolve(true);
            }
        });
    }

    static async prompt({ message, confirmText = 'Speichern', type = 'text', placeholder = '' }) {
        return BaseDialog.show({
            dialogClassName: 'custom-dialog prompt-dialog',
            onEscapeValue: null,
            render: (dialog, overlay, resolve, cleanup) => {
                const msgSpan = document.createElement('div');
                msgSpan.className = 'unsaved-msg';
                msgSpan.textContent = message;
                msgSpan.style.marginBottom = '12px';

                const input = document.createElement('input');
                input.type = type;
                input.placeholder = placeholder;
                input.className = 'dialog-input';
                input.style.display = 'block';
                input.style.width = '100%';
                input.style.marginBottom = '16px';

                const confirmBtn = document.createElement('button');
                confirmBtn.className = 'save-btn-header';
                confirmBtn.textContent = confirmText;

                const cancelBtn = document.createElement('button');
                cancelBtn.className = 'discard-btn-header';
                cancelBtn.textContent = 'Abbrechen';

                confirmBtn.addEventListener('click', () => resolve(input.value));
                cancelBtn.addEventListener('click', () => resolve(null));

                dialog.appendChild(msgSpan);
                dialog.appendChild(input);
                dialog.appendChild(cancelBtn);
                dialog.appendChild(confirmBtn);

                setTimeout(() => input.focus(), 50);
            },
            onKeydown: (e, dialog, overlay, resolve) => {
                if (e.key === 'Enter') resolve(dialog.querySelector('input').value);
            }
        });
    }

    static async alert({ message, title = 'Info' }) {
        return BaseDialog.show({
            onEscapeValue: undefined,
            render: (dialog, overlay, resolve, cleanup) => {
                const titleEl = document.createElement('div');
                titleEl.className = 'unsaved-msg';
                titleEl.style.fontWeight = '700';
                titleEl.style.marginBottom = '8px';
                titleEl.textContent = title;

                const msgSpan = document.createElement('div');
                msgSpan.className = 'unsaved-msg';
                msgSpan.innerHTML = message.replace(/\n/g, '<br>');
                msgSpan.style.marginBottom = '16px';
                msgSpan.style.fontSize = '13px';
                msgSpan.style.lineHeight = '1.5';

                const okBtn = document.createElement('button');
                okBtn.className = 'save-btn-header';
                okBtn.textContent = 'OK';
                okBtn.style.margin = '0 auto';
                okBtn.style.display = 'block';

                okBtn.addEventListener('click', () => resolve());

                dialog.appendChild(titleEl);
                dialog.appendChild(msgSpan);
                dialog.appendChild(okBtn);

                okBtn.focus();
            },
            onKeydown: (e, dialog, overlay, resolve) => {
                if (e.key === 'Enter') resolve();
            }
        });
    }

    static async showAddColumnDialog(tableId, availableEnums = []) {
        return BaseDialog.show({
            onEscapeValue: null,
            render: (dialog, overlay, resolve, cleanup) => {
                overlay.style.zIndex = '10000';

                dialog.style.flexDirection = 'column';
                dialog.style.width = '460px'; // Slightly wider for row layout
                dialog.style.alignItems = 'stretch';
                dialog.style.gap = '16px';

                const title = document.createElement('div');
                title.className = 'unsaved-msg';
                title.style.fontWeight = '700';
                title.style.marginBottom = '8px';
                title.textContent = 'Neue Spalte hinzufügen';
                dialog.appendChild(title);

                const createRow = (labelText, inputEl) => {
                    const row = document.createElement('div');
                    row.style.display = 'flex';
                    row.style.alignItems = 'center';
                    row.style.justifyContent = 'space-between';
                    row.style.gap = '16px';

                    const lbl = document.createElement('div');
                    lbl.className = 'unsaved-msg';
                    lbl.style.fontSize = '13px';
                    lbl.style.whiteSpace = 'nowrap';
                    lbl.textContent = labelText;

                    inputEl.style.width = '240px';
                    inputEl.style.marginBottom = '0'; // Override previous default

                    row.appendChild(lbl);
                    row.appendChild(inputEl);
                    return row;
                };

                // Name
                const nameInput = document.createElement('input');
                nameInput.className = 'dialog-input';
                dialog.appendChild(createRow('Name der Spalte:', nameInput));

                // Type
                const typeSelect = document.createElement('select');
                typeSelect.className = 'dialog-input';
                ['text', 'int', 'number', 'date', 'time', 'boolean', 'enum'].forEach(t => {
                    const opt = document.createElement('option');
                    opt.value = t;
                    opt.textContent = t;
                    typeSelect.appendChild(opt);
                });
                dialog.appendChild(createRow('Datentyp:', typeSelect));

                // --- Enum Section ---
                const enumSelectionRowWrap = document.createElement('div');
                enumSelectionRowWrap.style.display = 'none';
                const enumSelect = document.createElement('select');
                enumSelect.className = 'dialog-input';

                const populateEnums = () => {
                    enumSelect.innerHTML = '';
                    const baseOpt = document.createElement('option');
                    baseOpt.value = '';
                    baseOpt.textContent = '-- Bestehenden Enum wählen --';
                    enumSelect.appendChild(baseOpt);

                    availableEnums.forEach(e => {
                        const opt = document.createElement('option');
                        opt.value = e;
                        opt.textContent = e;
                        enumSelect.appendChild(opt);
                    });

                    const newOpt = document.createElement('option');
                    newOpt.value = 'CREATE_NEW';
                    newOpt.textContent = '+ Neuen Enum erstellen...';
                    enumSelect.appendChild(newOpt);
                };
                populateEnums();
                enumSelectionRowWrap.appendChild(createRow('Welcher Enum?', enumSelect));
                dialog.appendChild(enumSelectionRowWrap);

                // New Enum Creation Section (Hidden initially)
                const newEnumInputs = document.createElement('div');
                newEnumInputs.style.display = 'none';
                newEnumInputs.style.flexDirection = 'column';
                newEnumInputs.style.gap = '12px';
                newEnumInputs.style.padding = '12px';
                newEnumInputs.style.background = 'var(--bg-secondary)';
                newEnumInputs.style.borderRadius = 'var(--radius-sm)';
                newEnumInputs.style.marginTop = '4px';

                const newEnumNameInput = document.createElement('input');
                newEnumNameInput.className = 'dialog-input';
                newEnumNameInput.placeholder = 'z.B. parkplatz_enum';
                newEnumInputs.appendChild(createRow('Enum-Name (DB):', newEnumNameInput));

                const newEnumOptionsInput = document.createElement('input');
                newEnumOptionsInput.className = 'dialog-input';
                newEnumOptionsInput.placeholder = 'Option A, Option B, ...';
                newEnumInputs.appendChild(createRow('Optionen:', newEnumOptionsInput));
                dialog.appendChild(newEnumInputs);

                typeSelect.onchange = () => {
                    const isEnum = typeSelect.value === 'enum';
                    enumSelectionRowWrap.style.display = isEnum ? 'block' : 'none';
                    if (!isEnum) newEnumInputs.style.display = 'none';
                };

                enumSelect.onchange = () => {
                    newEnumInputs.style.display = enumSelect.value === 'CREATE_NEW' ? 'flex' : 'none';
                };

                const actions = document.createElement('div');
                actions.style.display = 'flex';
                actions.style.justifyContent = 'flex-end';
                actions.style.gap = '12px';
                actions.style.marginTop = '8px';

                const cancelBtn = document.createElement('button');
                cancelBtn.className = 'discard-btn-header';
                cancelBtn.textContent = 'Abbrechen';

                const confirmBtn = document.createElement('button');
                confirmBtn.className = 'save-btn-header';
                confirmBtn.textContent = 'Hinzufügen';

                cancelBtn.onclick = () => { resolve(null); };
                confirmBtn.onclick = () => {
                    const nameValue = nameInput.value.trim();
                    const typeValue = typeSelect.value;
                    if (!nameValue) return; // Flash handled by caller or simple return

                    let result = { name: nameValue, type: typeValue };

                    if (typeValue === 'enum') {
                        if (enumSelect.value === 'CREATE_NEW') {
                            const newName = newEnumNameInput.value.trim();
                            const options = newEnumOptionsInput.value.split(',').map(o => o.trim()).filter(o => o);
                            if (!newName || options.length === 0) return alert('Name und Optionen für neuen Enum erforderlich');
                            result.newEnum = { name: newName, options };
                            result.type = newName;
                        } else if (enumSelect.value) {
                            result.type = enumSelect.value;
                        } else {
                            return alert('Bitte einen Enum wählen');
                        }
                    }

                    resolve(result);
                };

                actions.appendChild(cancelBtn);
                actions.appendChild(confirmBtn);
                dialog.appendChild(actions);

                setTimeout(() => nameInput.focus(), 50);
            }
        });
    }

    static async showConflictDialog(conflictCount) {
        return BaseDialog.show({
            onEscapeValue: 'cancel',
            render: (dialog, overlay, resolve, cleanup) => {
                const msgSpan = document.createElement('span');
                msgSpan.className = 'unsaved-msg';
                msgSpan.textContent = `${conflictCount} Zeile(n) wurden von einem anderen Benutzer bearbeitet.`;

                const overwriteBtn = document.createElement('button');
                overwriteBtn.className = 'discard-btn-header';
                overwriteBtn.textContent = 'Überschreiben';

                const reloadBtn = document.createElement('button');
                reloadBtn.className = 'save-btn-header';
                reloadBtn.textContent = 'Neu laden';

                const cancelBtn = document.createElement('button');
                cancelBtn.className = 'discard-btn-header';
                cancelBtn.textContent = 'Abbrechen';

                overwriteBtn.addEventListener('click', () => resolve('overwrite'));
                reloadBtn.addEventListener('click', () => resolve('reload'));
                cancelBtn.addEventListener('click', () => resolve('cancel'));

                dialog.appendChild(msgSpan);
                dialog.appendChild(cancelBtn);
                dialog.appendChild(reloadBtn);
                dialog.appendChild(overwriteBtn);

                reloadBtn.focus();
            },
            onKeydown: (e, dialog, overlay, resolve) => {
                if (e.key === 'Enter') resolve('reload');
            }
        });
    }
}

import '../styles/Header.css';
import { GlobalStateManager } from '../core/GlobalStateManager.js';
import { AuditLogsDialog } from './AuditLogsDialog.js';

/**
 * Header - Main application header with navigation and theme toggle
 */
export class Header {
    constructor({ appName = 'Activity Manager', onThemeToggle, onTableSwitch, tableConfigs = [], tables = {} }) {
        this.appName = appName;
        this.onThemeToggle = onThemeToggle;
        this.onTableSwitch = onTableSwitch;
        this.onCalendarToggle = null;
        this.tableConfigs = tableConfigs;
        this.tables = tables;
        this.currentTable = tableConfigs[0]?.id || 'games';
        this.element = null;
        this.personsSplitOpen = false;
        this.inventorySplitOpen = false;
        this.calendarSplitOpen = false;
        this.onFavoritesToggle = null;
        this.onLogoDoubleClick = null;
        this.onCalendarFull = null;
        this.favoritesActive = false;
        this.currentResults = [];
        this.selectedIndex = -1;

        GlobalStateManager.getInstance().onFlashMessageCallback((msg, type) => this.showFlash(msg, type));
    }

    render() {
        this.element = document.createElement('header');
        this.element.className = 'app-header';
        this.element.innerHTML = this._getHeaderHTML();

        this._attachEventListeners();
        this._updateThemeUI();

        return this.element;
    }

    _updateThemeUI() {
        if (!this.element) return;
        const isDark = document.documentElement.dataset.theme === 'dark';
        const icon = this.element.querySelector('.theme-icon');
        if (icon) {
            icon.textContent = isDark ? 'Light Mode' : 'Dark Mode';
        }
        const btn = this.element.querySelector('.theme-toggle');
        if (btn) {
            btn.title = isDark ? 'Lichtmodus umschalten' : 'Dunkelmodus umschalten';
        }
    }

    _getHeaderHTML() {
        const globalState = GlobalStateManager.getInstance();

        // Filter configurations based on current view permissions
        const viewableConfigs = this.tableConfigs.filter(t => globalState.canView(t.id));

        // Categories
        const spieleTables = viewableConfigs.filter(t => t.category === 'spiele');
        const sportTables = viewableConfigs.filter(t => t.category === 'sportarten');
        const otherTables = viewableConfigs.filter(t => !t.category && !['tbl_people', 'tbl_inventory', 'tbl_ort'].includes(t.id));

        // Permissions for split-views
        const canViewPeople = globalState.canView('people_table') || globalState.canView('tbl_people');
        const canViewInventory = globalState.canView('tbl_inventory');

        return `
            <div class="header-left" title="do NOT double click">
                <span class="header-logo">⬡</span>
                <div class="logo-stack">
                    <span class="header-title">${this.appName}</span>
                    <span class="header-version">v2.3.2</span>
                </div>
            </div>
            <nav class="header-nav">
                ${this._renderCategoryButton(spieleTables, 'spiele', 'Spiele')}
                ${this._renderCategoryButton(sportTables, 'sportarten', 'Sportarten')}
                ${otherTables.map((config, idx) =>
            `<button class="nav-btn ${idx === 0 && spieleTables.length === 0 ? 'active' : ''}" data-table="${config.id}">${config.title}</button>`
        ).join('')}

                ${canViewPeople ? `
                <button class="nav-btn persons-toggle-btn" title="Personen-Ansicht umschalten">
                    Personen
                </button>` : ''}

                ${canViewInventory ? `
                <button class="nav-btn inventory-toggle-btn" title="Inventar-Ansicht umschalten">
                    Inventar
                </button>` : ''}

                ${globalState.isEditModeActive() ? `
                <button class="nav-btn orte-btn" data-table="tbl_ort" title="Orte verwalten">
                    Orte
                </button>` : ''}
            </nav>
            <div class="header-center">
                <div class="header-search-container">
                    <input type="text" class="header-search-input" placeholder="Suchen..." aria-label="Global search">
                    <div class="search-results-dropdown"></div>
                </div>
                <div class="flash-banner" style="display: none;"></div>
                <div class="unsaved-banner" style="display: none;">
                    <span class="unsaved-msg">Ungespeicherte Änderungen vorhanden</span>
                    <button class="save-btn-header">Speichern</button>
                    <button class="discard-btn-header">Verwerfen</button>
                    <div class="save-loading-bar"></div>
                </div>
            </div>
            <div class="header-right">
                ${globalState.canViewLogs() ? `
                    <button class="nav-btn audit-logs-btn" title="Audit Logs ansehen" style="border-color:var(--text-secondary); color:var(--text-secondary)">
                        Logs
                    </button>
                ` : ''}
                ${globalState.canSeeStats() ? `
                    <button class="nav-btn user-info-btn" title="System-Stats und Berechtigungen">
                        Stats
                    </button>
                ` : ''}
                ${globalState.isEditModeActive() ? `
                    <button class="nav-btn add-table-btn" style="border-color:var(--warning); color:var(--warning)" title="Neue Kategorie erstellen">
                        + Kategorie
                    </button>
                ` : ''}
                <button class="nav-btn calendar-toggle-btn" title="Kalender öffnen">
                    Kalender
                </button>
                <div class="dropdown-container user-dropdown-container">
                    <button class="header-user user-menu-btn">
                        ${globalState.getCurrentUser()} <span class="dropdown-arrow" style="margin-left: 6px;">▼</span>
                    </button>
                    <div class="dropdown-menu user-dropdown-menu">
                        ${globalState.canUseEditMode() ? `
                            <button class="dropdown-item edit-mode-btn ${globalState.isEditModeActive() ? 'active' : ''}">
                                ${globalState.isEditModeActive() ? 'Edit-Modus deaktivieren' : 'Edit-Modus aktivieren'}
                            </button>
                        ` : ''}
                        <button class="dropdown-item favorites-toggle-btn">Favoriten</button>
                        <button class="dropdown-item change-password-btn">Passwort ändern</button>
                        <button class="dropdown-item logout-btn">Abmelden</button>
                    </div>
                </div>
                <button class="theme-toggle" aria-label="Design umschalten" title="Dunkelmodus umschalten">
                    <span class="theme-icon">Dark Mode</span>
                </button>
            </div>
        `;
    }

    _renderCategoryButton(categoryTables, categoryId, categoryLabel) {
        if (categoryTables.length === 0) return '';

        // If only ONE table is allowed in this category, show it as a simple button
        if (categoryTables.length === 1) {
            const table = categoryTables[0];
            return `<button class="nav-btn ${this.currentTable === table.id ? 'active' : ''}" data-table="${table.id}">${table.title}</button>`;
        }

        // Multiple tables allowed -> Show split-button dropdown
        return `
            <div class="dropdown-container split-btn-group">
                <button class="nav-btn split-main-btn" data-table="all-${categoryId}">
                    ${categoryLabel}
                </button>
                <div class="split-divider"></div>
                <button class="nav-btn split-arrow-btn dropdown-btn" aria-label="${categoryLabel} Menü öffnen">
                    <span class="dropdown-arrow">▼</span>
                </button>
                <div class="dropdown-menu">
                    ${categoryTables.map(t => `<button class="dropdown-item" data-table="${t.id}">${t.title}</button>`).join('')}
                </div>
            </div>
        `;
    }

    _attachEventListeners() {
        if (!this.element) return;


        this.element.addEventListener('click', async (e) => {
            const btn = e.target.closest('.nav-btn, .dropdown-item');
            if (btn && btn.dataset.table) {
                const tableId = btn.dataset.table;
                this.switchTo(tableId);
                this.onTableSwitch?.(tableId);
                this._closeAllDropdowns();
            }

            if (e.target.closest('.theme-toggle')) {
                const rect = e.target.closest('.theme-toggle').getBoundingClientRect();
                const clickX = e.clientX || rect.left + rect.width / 2;
                const clickY = e.clientY || rect.top + rect.height / 2;
                await this.onThemeToggle?.(clickX, clickY);
                this._updateThemeUI();
            }

            if (e.target.closest('.persons-toggle-btn')) {
                this.onPersonsToggle?.();
            }

            if (e.target.closest('.inventory-toggle-btn')) {
                this.onInventoryToggle?.();
            }

            if (e.target.closest('.orte-btn')) {
                this.onTableSwitch?.('tbl_ort');
            }

            if (e.target.closest('.user-info-btn')) {
                this.onUserInfo?.();
            }

            if (e.target.closest('.add-table-btn')) {
                const name = prompt('Name für die neue Kategorie (z.B. Escape Rooms):');
                if (name) {
                    try {
                        const gs = GlobalStateManager.getInstance();
                        const slug = name.toLowerCase().replace(/\s+/g, '_');
                        // 1. Add to activity_category_enum
                        await gs.addEnumOption('activity_category_enum', slug);
                        // 2. Update local tables.json (simulated or instructions given)
                        alert(`Kategorie '${name}' in DB erstellt. Bitte füge 'tbl_activities_${slug}' zu tables.json hinzu.`);
                        window.location.reload();
                    } catch (err) {
                        alert(`Fehler: ${err.message}`);
                    }
                }
            }

            if (e.target.closest('.calendar-toggle-btn')) {
                this._closeAllDropdowns();
                // Simple click handles split view toggle
                this.onCalendarToggle?.();
            }

            if (e.target.closest('.logout-btn')) {
                this.onLogout?.();
            }

            if (e.target.closest('.change-password-btn')) {
                this.onChangePassword?.();
            }

            if (e.target.closest('.edit-mode-btn')) {
                const btn = e.target.closest('.edit-mode-btn');
                const isActive = btn.textContent.includes('deaktivieren');
                if (isActive) {
                    btn.textContent = 'Edit-Modus aktivieren';
                    btn.classList.remove('active');
                } else {
                    btn.textContent = 'Edit-Modus deaktivieren';
                    btn.classList.add('active');
                }
                this.onEditModeToggle?.(!isActive);
            }

            if (e.target.closest('.favorites-toggle-btn')) {
                this.favoritesActive = !this.favoritesActive;
                e.target.closest('.favorites-toggle-btn').classList.toggle('active', this.favoritesActive);
                this.onFavoritesToggle?.(this.favoritesActive);
            }

            if (e.target.closest('.audit-logs-btn')) {
                await AuditLogsDialog.show();
            }

            // Dropdown toggles
            const dropdownBtn = e.target.closest('.dropdown-btn, .user-menu-btn');
            if (dropdownBtn) {
                e.stopPropagation(); // Prevent global window click from closing it immediately
                const container = dropdownBtn.closest('.dropdown-container');
                const isShowing = container.classList.contains('show');
                this._closeAllDropdowns();
                if (!isShowing) container.classList.add('show');
            } else if (!e.target.closest('.dropdown-menu')) {
                this._closeAllDropdowns();
            }
        });

        // Logo double click for Blackjack
        const logo = this.element.querySelector('.header-left');
        if (logo) {
            logo.addEventListener('dblclick', () => {
                this.onLogoDoubleClick?.();
            });
        }

        // Split view buttons double click for full screen
        const personsBtn = this.element.querySelector('.persons-toggle-btn');
        if (personsBtn) {
            personsBtn.addEventListener('dblclick', () => {
                this.onPersonsFullView?.();
            });
        }

        const inventoryBtn = this.element.querySelector('.inventory-toggle-btn');
        if (inventoryBtn) {
            inventoryBtn.addEventListener('dblclick', () => {
                this.onInventoryFullView?.();
            });
        }

        const calendarBtn = this.element.querySelector('.calendar-toggle-btn');
        if (calendarBtn) {
            calendarBtn.addEventListener('dblclick', (e) => {
                e.stopPropagation();
                this.onCalendarFull?.();
            });
        }

        // Unsaved changes banner
        const saveBtn = this.element.querySelector('.save-btn-header');
        if (saveBtn) {
            saveBtn.addEventListener('click', () => {
                this.onSaveAll?.();
            });
        }

        const discardBtn = this.element.querySelector('.discard-btn-header');
        if (discardBtn) {
            discardBtn.addEventListener('click', () => {
                this.onDiscardAll?.();
            });
        }

        // Search bar
        const searchInput = this.element.querySelector('.header-search-input');
        const resultsDropdown = this.element.querySelector('.search-results-dropdown');

        if (searchInput) {
            searchInput.addEventListener('input', (e) => {
                this._handleSearch(e.target.value);
            });

            searchInput.addEventListener('focus', () => {
                if (searchInput.value.trim().length >= 2) {
                    resultsDropdown.classList.add('show');
                }
            });

            searchInput.addEventListener('keydown', (e) => {
                if (e.key === 'ArrowDown') {
                    e.preventDefault();
                    if (this.currentResults.length > 0) {
                        this.selectedIndex = (this.selectedIndex + 1) % this.currentResults.length;
                        this._updateSelectedResultUI();
                    }
                } else if (e.key === 'ArrowUp') {
                    e.preventDefault();
                    if (this.currentResults.length > 0) {
                        this.selectedIndex = (this.selectedIndex - 1 + this.currentResults.length) % this.currentResults.length;
                        this._updateSelectedResultUI();
                    }
                } else if (e.key === 'Enter') {
                    const idx = this.selectedIndex >= 0 ? this.selectedIndex : 0;
                    if (this.currentResults[idx]) {
                        const res = this.currentResults[idx];
                        this.switchTo(res.tableId);
                        this.onTableSwitch?.(res.tableId, res.rowId, res.colId);
                        resultsDropdown.classList.remove('show');
                        searchInput.value = '';
                        searchInput.blur();
                    }
                }
            });
        }

        // Close search results on outside click
        document.addEventListener('click', (e) => {
            if (!e.target.closest('.header-search-container')) {
                resultsDropdown?.classList.remove('show');
            }
        });

        // Handle result clicks
        resultsDropdown?.addEventListener('click', (e) => {
            const item = e.target.closest('.search-result-item');
            if (item && item.dataset.tableId) {
                const tableId = item.dataset.tableId;
                const rowId = item.dataset.rowId;
                const colId = item.dataset.colId;
                this.switchTo(tableId);
                this.onTableSwitch?.(tableId, rowId, colId);
                resultsDropdown.classList.remove('show');
                searchInput.value = '';
            }
        });

        // Update selected index on mouse move
        resultsDropdown?.addEventListener('mouseover', (e) => {
            const item = e.target.closest('.search-result-item');
            if (item && item.dataset.index) {
                this.selectedIndex = parseInt(item.dataset.index);
                this._updateSelectedResultUI();
            }
        });
    }

    _handleSearch(query) {
        const resultsDropdown = this.element.querySelector('.search-results-dropdown');
        const trimmedQuery = query.trim();

        if (trimmedQuery.length < 2) {
            resultsDropdown.classList.remove('show');
            resultsDropdown.innerHTML = '';
            this.currentResults = [];
            this.selectedIndex = -1;
            return;
        }

        const results = [];
        const globalState = GlobalStateManager.getInstance();

        // Iterate over all tables
        Object.entries(this.tables).forEach(([tableId, data]) => {
            if (!globalState.canView(tableId)) return;

            const { instance, instances, config } = data;
            const targetInstances = instances || [instance];
            const tableTitle = config.title;

            targetInstances.forEach(inst => {
                if (!inst || !inst.rows) return;

                inst.rows.forEach(row => {
                    Object.entries(row.data).forEach(([colId, value]) => {
                        if (value === null || value === undefined) return;

                        const strValue = String(value);
                        if (strValue.toLowerCase().includes(trimmedQuery.toLowerCase())) {
                            const colDef = inst.schema.find(c => c.id === colId);
                            // Avoid duplicate results for the same row in same table if we already found a match
                            // (Actually the user wants column name, so multiple columns in same row are fine)
                            results.push({
                                tableId,
                                tableTitle,
                                colId,
                                colLabel: colDef ? colDef.label : colId,
                                value: strValue,
                                rowId: row.id
                            });
                        }
                    });
                });
            });
        });

        this.currentResults = results.slice(0, 5);
        this.selectedIndex = this.currentResults.length > 0 ? 0 : -1;
        this._renderSearchResults(this.currentResults, trimmedQuery);
    }

    _renderSearchResults(results, query) {
        const resultsDropdown = this.element.querySelector('.search-results-dropdown');
        if (!resultsDropdown) return;

        if (results.length === 0) {
            resultsDropdown.innerHTML = '<div class="no-results">Keine Ergebnisse gefunden</div>';
        } else {
            resultsDropdown.innerHTML = results.map((res, i) => `
                <div class="search-result-item ${i === this.selectedIndex ? 'selected' : ''}"
                     data-index="${i}"
                     data-table-id="${res.tableId}"
                     data-row-id="${res.rowId}"
                     data-col-id="${res.colId}">
                    <div class="result-meta">
                        <span class="result-table-name">${res.tableTitle}</span>
                        <span class="result-col-name">${res.colLabel}</span>
                    </div>
                    <div class="result-content">
                        ${this._highlightSearchTerm(res.value, query)}
                    </div>
                </div>
            `).join('');
        }

        resultsDropdown.classList.add('show');
    }

    _updateSelectedResultUI() {
        const resultsDropdown = this.element.querySelector('.search-results-dropdown');
        if (!resultsDropdown) return;

        resultsDropdown.querySelectorAll('.search-result-item').forEach((item, i) => {
            item.classList.toggle('selected', i === this.selectedIndex);
        });
    }

    _highlightSearchTerm(text, query) {
        if (!query) return text;
        const regex = new RegExp(`(${query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi');
        return text.replace(regex, '<span class="search-highlight">$1</span>');
    }

    _closeAllDropdowns() {
        this.element.querySelectorAll('.dropdown-container').forEach(c => c.classList.remove('show'));
    }

    switchTo(table) {
        this.currentTable = table;
        this.element.querySelectorAll('.nav-btn:not(.persons-toggle-btn):not(.inventory-toggle-btn):not(.calendar-toggle-btn)').forEach(btn => {
            btn.classList.toggle('active', btn.dataset.table === table);
        });
    }

    showUnsavedBanner() {
        const banner = this.element.querySelector('.unsaved-banner');
        if (banner) {
            banner.style.display = 'flex';
            this.setLoading(false); // Reset loading state when showing banner
        }
    }

    hideUnsavedBanner() {
        const banner = this.element.querySelector('.unsaved-banner');
        if (banner) {
            banner.style.display = 'none';
            this.setLoading(false);
        }
    }

    setLoading(isLoading) {
        const banner = this.element.querySelector('.unsaved-banner');
        if (!banner) return;
        const msg = banner.querySelector('.unsaved-msg');
        const saveBtn = banner.querySelector('.save-btn-header');
        const discardBtn = banner.querySelector('.discard-btn-header');
        const bar = banner.querySelector('.save-loading-bar');

        if (isLoading) {
            document.body.classList.add('global-loading');
            if (msg) msg.textContent = 'Speichere...';
            if (saveBtn) {
                saveBtn.disabled = true;
                saveBtn.textContent = 'Speichern...';
            }
            if (discardBtn) discardBtn.disabled = true;
            if (bar) bar.style.display = 'block';
        } else {
            document.body.classList.remove('global-loading');
            if (msg) msg.textContent = 'Ungespeicherte Änderungen vorhanden';
            if (saveBtn) {
                saveBtn.disabled = false;
                saveBtn.textContent = 'Speichern';
            }
            if (discardBtn) discardBtn.disabled = false;
            if (bar) bar.style.display = 'none';
        }
    }

    showFlash(message, type = 'success') {
        const banner = this.element.querySelector('.flash-banner');
        if (!banner) return;

        banner.textContent = message;
        banner.className = `flash-banner flash-${type}`;
        banner.style.display = 'block';
        banner.style.opacity = '1';

        setTimeout(() => {
            banner.style.opacity = '0';
            setTimeout(() => {
                banner.style.display = 'none';
            }, 300);
        }, 3000);
    }
}

import '../styles/Header.css';
import { GlobalStateManager } from '../core/GlobalStateManager.js';
import { AuditLogsDialog } from './AuditLogsDialog.js';

/**
 * Header - Main application header with navigation and theme toggle
 */
export class Header {
    constructor({ appName = 'Activity Manager', onThemeToggle, onTableSwitch, tableConfigs = [], tables = {} }) {
        this.appName = appName;
        this.onThemeToggle = onThemeToggle;
        this.onTableSwitch = onTableSwitch;
        this.onCalendarToggle = null;
        this.tableConfigs = tableConfigs;
        this.tables = tables;
        this.currentTable = tableConfigs[0]?.id || 'games';
        this.element = null;
        this.personsSplitOpen = false;
        this.inventorySplitOpen = false;
        this.calendarSplitOpen = false;
        this.onFavoritesToggle = null;
        this.onLogoDoubleClick = null;
        this.onCalendarFull = null;
        this.favoritesActive = false;
        this.currentResults = [];
        this.selectedIndex = -1;
        this.version = this._getVersion();

        GlobalStateManager.getInstance().onFlashMessageCallback((msg, type) => this.showFlash(msg, type));
    }

    async _getVersion() {
        try {
            const response = await fetch('/package.json');
            const pkg = await response.json();
            return pkg.version || 'unknown';
        } catch (e) {
            return 'unknown';
        }
    }

    render() {
        this.element = document.createElement('header');
        this.element.className = 'app-header';
        this.element.innerHTML = this._getHeaderHTML();

        this._attachEventListeners();
        this._updateThemeUI();

        return this.element;
    }

    _updateThemeUI() {
        if (!this.element) return;
        const isDark = document.documentElement.dataset.theme === 'dark';
        const icon = this.element.querySelector('.theme-icon');
        if (icon) {
            icon.textContent = isDark ? 'Light Mode' : 'Dark Mode';
        }
        const btn = this.element.querySelector('.theme-toggle');
        if (btn) {
            btn.title = isDark ? 'Lichtmodus umschalten' : 'Dunkelmodus umschalten';
        }
    }

    _getHeaderHTML() {
        const globalState = GlobalStateManager.getInstance();

        // Filter configurations based on current view permissions
        const viewableConfigs = this.tableConfigs.filter(t => globalState.canView(t.id));

        // Categories
        const spieleTables = viewableConfigs.filter(t => t.category === 'spiele');
        const sportTables = viewableConfigs.filter(t => t.category === 'sportarten');
        const otherTables = viewableConfigs.filter(t => !t.category && !['tbl_people', 'tbl_inventory', 'tbl_ort'].includes(t.id));

        // Permissions for split-views
        const canViewPeople = globalState.canView('people_table') || globalState.canView('tbl_people');
        const canViewInventory = globalState.canView('tbl_inventory');

        return `
            <div class="header-left" title="do NOT double click">
                <span class="header-logo">⬡</span>
                <div class="logo-stack">
                    <span class="header-title">${this.appName}</span>
                    <span class="header-version">v${this.version}</span>
                </div>
            </div>
            <nav class="header-nav">
                ${this._renderCategoryButton(spieleTables, 'spiele', 'Spiele')}
                ${this._renderCategoryButton(sportTables, 'sportarten', 'Sportarten')}
                ${otherTables.map((config, idx) =>
            `<button class="nav-btn ${idx === 0 && spieleTables.length === 0 ? 'active' : ''}" data-table="${config.id}">${config.title}</button>`
        ).join('')}

                ${canViewPeople ? `
                <button class="nav-btn persons-toggle-btn" title="Personen-Ansicht umschalten">
                    Personen
                </button>` : ''}

                ${canViewInventory ? `
                <button class="nav-btn inventory-toggle-btn" title="Inventar-Ansicht umschalten">
                    Inventar
                </button>` : ''}

                ${globalState.isEditModeActive() ? `
                <button class="nav-btn orte-btn" data-table="tbl_ort" title="Orte verwalten">
                    Orte
                </button>` : ''}
            </nav>
            <div class="header-center">
                <div class="header-search-container">
                    <input type="text" class="header-search-input" placeholder="Suchen..." aria-label="Global search">
                    <div class="search-results-dropdown"></div>
                </div>
                <div class="flash-banner" style="display: none;"></div>
                <div class="unsaved-banner" style="display: none;">
                    <span class="unsaved-msg">Ungespeicherte Änderungen vorhanden</span>
                    <button class="save-btn-header">Speichern</button>
                    <button class="discard-btn-header">Verwerfen</button>
                    <div class="save-loading-bar"></div>
                </div>
            </div>
            <div class="header-right">
                ${globalState.canViewLogs() ? `
                    <button class="nav-btn audit-logs-btn" title="Audit Logs ansehen" style="border-color:var(--text-secondary); color:var(--text-secondary)">
                        Logs
                    </button>
                ` : ''}
                ${globalState.canSeeStats() ? `
                    <button class="nav-btn user-info-btn" title="System-Stats und Berechtigungen">
                        Stats
                    </button>
                ` : ''}
                ${globalState.isEditModeActive() ? `
                    <button class="nav-btn add-table-btn" style="border-color:var(--warning); color:var(--warning)" title="Neue Kategorie erstellen">
                        + Kategorie
                    </button>
                ` : ''}
                <button class="nav-btn calendar-toggle-btn" title="Kalender öffnen">
                    Kalender
                </button>
                <div class="dropdown-container user-dropdown-container">
                    <button class="header-user user-menu-btn">
                        ${globalState.getCurrentUser()} <span class="dropdown-arrow" style="margin-left: 6px;">▼</span>
                    </button>
                    <div class="dropdown-menu user-dropdown-menu">
                        ${globalState.canUseEditMode() ? `
                            <button class="dropdown-item edit-mode-btn ${globalState.isEditModeActive() ? 'active' : ''}">
                                ${globalState.isEditModeActive() ? 'Edit-Modus deaktivieren' : 'Edit-Modus aktivieren'}
                            </button>
                        ` : ''}
                        <button class="dropdown-item favorites-toggle-btn">Favoriten</button>
                        <button class="dropdown-item change-password-btn">Passwort ändern</button>
                        <button class="dropdown-item logout-btn">Abmelden</button>
                    </div>
                </div>
                <button class="theme-toggle" aria-label="Design umschalten" title="Dunkelmodus umschalten">
                    <span class="theme-icon">Dark Mode</span>
                </button>
            </div>
        `;
    }

    _renderCategoryButton(categoryTables, categoryId, categoryLabel) {
        if (categoryTables.length === 0) return '';

        // If only ONE table is allowed in this category, show it as a simple button
        if (categoryTables.length === 1) {
            const table = categoryTables[0];
            return `<button class="nav-btn ${this.currentTable === table.id ? 'active' : ''}" data-table="${table.id}">${table.title}</button>`;
        }

        // Multiple tables allowed -> Show split-button dropdown
        return `
            <div class="dropdown-container split-btn-group">
                <button class="nav-btn split-main-btn" data-table="all-${categoryId}">
                    ${categoryLabel}
                </button>
                <div class="split-divider"></div>
                <button class="nav-btn split-arrow-btn dropdown-btn" aria-label="${categoryLabel} Menü öffnen">
                    <span class="dropdown-arrow">▼</span>
                </button>
                <div class="dropdown-menu">
                    ${categoryTables.map(t => `<button class="dropdown-item" data-table="${t.id}">${t.title}</button>`).join('')}
                </div>
            </div>
        `;
    }

    _attachEventListeners() {
        if (!this.element) return;


        this.element.addEventListener('click', async (e) => {
            const btn = e.target.closest('.nav-btn, .dropdown-item');
            if (btn && btn.dataset.table) {
                const tableId = btn.dataset.table;
                this.switchTo(tableId);
                this.onTableSwitch?.(tableId);
                this._closeAllDropdowns();
            }

            if (e.target.closest('.theme-toggle')) {
                const rect = e.target.closest('.theme-toggle').getBoundingClientRect();
                const clickX = e.clientX || rect.left + rect.width / 2;
                const clickY = e.clientY || rect.top + rect.height / 2;
                await this.onThemeToggle?.(clickX, clickY);
                this._updateThemeUI();
            }

            if (e.target.closest('.persons-toggle-btn')) {
                this.onPersonsToggle?.();
            }

            if (e.target.closest('.inventory-toggle-btn')) {
                this.onInventoryToggle?.();
            }

            if (e.target.closest('.orte-btn')) {
                this.onTableSwitch?.('tbl_ort');
            }

            if (e.target.closest('.user-info-btn')) {
                this.onUserInfo?.();
            }

            if (e.target.closest('.add-table-btn')) {
                const name = prompt('Name für die neue Kategorie (z.B. Escape Rooms):');
                if (name) {
                    try {
                        const gs = GlobalStateManager.getInstance();
                        const slug = name.toLowerCase().replace(/\s+/g, '_');
                        // 1. Add to activity_category_enum
                        await gs.addEnumOption('activity_category_enum', slug);
                        // 2. Update local tables.json (simulated or instructions given)
                        alert(`Kategorie '${name}' in DB erstellt. Bitte füge 'tbl_activities_${slug}' zu tables.json hinzu.`);
                        window.location.reload();
                    } catch (err) {
                        alert(`Fehler: ${err.message}`);
                    }
                }
            }

            if (e.target.closest('.calendar-toggle-btn')) {
                this._closeAllDropdowns();
                // Simple click handles split view toggle
                this.onCalendarToggle?.();
            }

            if (e.target.closest('.logout-btn')) {
                this.onLogout?.();
            }

            if (e.target.closest('.change-password-btn')) {
                this.onChangePassword?.();
            }

            if (e.target.closest('.edit-mode-btn')) {
                const btn = e.target.closest('.edit-mode-btn');
                const isActive = btn.textContent.includes('deaktivieren');
                if (isActive) {
                    btn.textContent = 'Edit-Modus aktivieren';
                    btn.classList.remove('active');
                } else {
                    btn.textContent = 'Edit-Modus deaktivieren';
                    btn.classList.add('active');
                }
                this.onEditModeToggle?.(!isActive);
            }

            if (e.target.closest('.favorites-toggle-btn')) {
                this.favoritesActive = !this.favoritesActive;
                e.target.closest('.favorites-toggle-btn').classList.toggle('active', this.favoritesActive);
                this.onFavoritesToggle?.(this.favoritesActive);
            }

            if (e.target.closest('.audit-logs-btn')) {
                await AuditLogsDialog.show();
            }

            // Dropdown toggles
            const dropdownBtn = e.target.closest('.dropdown-btn, .user-menu-btn');
            if (dropdownBtn) {
                e.stopPropagation(); // Prevent global window click from closing it immediately
                const container = dropdownBtn.closest('.dropdown-container');
                const isShowing = container.classList.contains('show');
                this._closeAllDropdowns();
                if (!isShowing) container.classList.add('show');
            } else if (!e.target.closest('.dropdown-menu')) {
                this._closeAllDropdowns();
            }
        });

        // Logo double click for Blackjack
        const logo = this.element.querySelector('.header-left');
        if (logo) {
            logo.addEventListener('dblclick', () => {
                this.onLogoDoubleClick?.();
            });
        }

        // Split view buttons double click for full screen
        const personsBtn = this.element.querySelector('.persons-toggle-btn');
        if (personsBtn) {
            personsBtn.addEventListener('dblclick', () => {
                this.onPersonsFullView?.();
            });
        }

        const inventoryBtn = this.element.querySelector('.inventory-toggle-btn');
        if (inventoryBtn) {
            inventoryBtn.addEventListener('dblclick', () => {
                this.onInventoryFullView?.();
            });
        }

        const calendarBtn = this.element.querySelector('.calendar-toggle-btn');
        if (calendarBtn) {
            calendarBtn.addEventListener('dblclick', (e) => {
                e.stopPropagation();
                this.onCalendarFull?.();
            });
        }

        // Unsaved changes banner
        const saveBtn = this.element.querySelector('.save-btn-header');
        if (saveBtn) {
            saveBtn.addEventListener('click', () => {
                this.onSaveAll?.();
            });
        }

        const discardBtn = this.element.querySelector('.discard-btn-header');
        if (discardBtn) {
            discardBtn.addEventListener('click', () => {
                this.onDiscardAll?.();
            });
        }

        // Search bar
        const searchInput = this.element.querySelector('.header-search-input');
        const resultsDropdown = this.element.querySelector('.search-results-dropdown');

        if (searchInput) {
            searchInput.addEventListener('input', (e) => {
                this._handleSearch(e.target.value);
            });

            searchInput.addEventListener('focus', () => {
                if (searchInput.value.trim().length >= 2) {
                    resultsDropdown.classList.add('show');
                }
            });

            searchInput.addEventListener('keydown', (e) => {
                if (e.key === 'ArrowDown') {
                    e.preventDefault();
                    if (this.currentResults.length > 0) {
                        this.selectedIndex = (this.selectedIndex + 1) % this.currentResults.length;
                        this._updateSelectedResultUI();
                    }
                } else if (e.key === 'ArrowUp') {
                    e.preventDefault();
                    if (this.currentResults.length > 0) {
                        this.selectedIndex = (this.selectedIndex - 1 + this.currentResults.length) % this.currentResults.length;
                        this._updateSelectedResultUI();
                    }
                } else if (e.key === 'Enter') {
                    const idx = this.selectedIndex >= 0 ? this.selectedIndex : 0;
                    if (this.currentResults[idx]) {
                        const res = this.currentResults[idx];
                        this.switchTo(res.tableId);
                        this.onTableSwitch?.(res.tableId, res.rowId, res.colId);
                        resultsDropdown.classList.remove('show');
                        searchInput.value = '';
                        searchInput.blur();
                    }
                }
            });
        }

        // Close search results on outside click
        document.addEventListener('click', (e) => {
            if (!e.target.closest('.header-search-container')) {
                resultsDropdown?.classList.remove('show');
            }
        });

        // Handle result clicks
        resultsDropdown?.addEventListener('click', (e) => {
            const item = e.target.closest('.search-result-item');
            if (item && item.dataset.tableId) {
                const tableId = item.dataset.tableId;
                const rowId = item.dataset.rowId;
                const colId = item.dataset.colId;
                this.switchTo(tableId);
                this.onTableSwitch?.(tableId, rowId, colId);
                resultsDropdown.classList.remove('show');
                searchInput.value = '';
            }
        });

        // Update selected index on mouse move
        resultsDropdown?.addEventListener('mouseover', (e) => {
            const item = e.target.closest('.search-result-item');
            if (item && item.dataset.index) {
                this.selectedIndex = parseInt(item.dataset.index);
                this._updateSelectedResultUI();
            }
        });
    }

    _handleSearch(query) {
        const resultsDropdown = this.element.querySelector('.search-results-dropdown');
        const trimmedQuery = query.trim().toLowerCase();

        if (trimmedQuery.length < 2) {
            resultsDropdown.classList.remove('show');
            resultsDropdown.innerHTML = '';
            this.currentResults = [];
            this.selectedIndex = -1;
            return;
        }

        const results = [];
        const globalState = GlobalStateManager.getInstance();

        // Iterate over all tables
        Object.entries(this.tables).forEach(([tableId, data]) => {
            if (!globalState.canView(tableId)) return;

            const { instance, instances, config } = data;
            const targetInstances = instances || [instance];
            const tableTitle = config.title;

            targetInstances.forEach(inst => {
                if (!inst || !inst.rows) return;

                inst.rows.forEach(row => {
                    Object.entries(row.data).forEach(([colId, value]) => {
                        if (value === null || value === undefined) return;

                        const strValue = String(value).toLowerCase();
                        const colDef = inst.schema.find(c => c.id === colId);

                        // Exact match (weight 2)
                        if (strValue === trimmedQuery) {
                            results.push({
                                tableId, tableTitle, colId,
                                colLabel: colDef ? colDef.label : colId,
                                value: String(value), rowId: row.id,
                                score: 100, type: 'exact'
                            });
                        }
                        // Starts with (weight 1.5)
                        else if (strValue.startsWith(trimmedQuery)) {
                            results.push({
                                tableId, tableTitle, colId,
                                colLabel: colDef ? colDef.label : colId,
                                value: String(value), rowId: row.id,
                                score: 75, type: 'start'
                            });
                        }
                        // Contains (weight 1)
                        else if (strValue.includes(trimmedQuery)) {
                            results.push({
                                tableId, tableTitle, colId,
                                colLabel: colDef ? colDef.label : colId,
                                value: String(value), rowId: row.id,
                                score: 50, type: 'contains'
                            });
                        }
                        // Fuzzy match (weight 0.5) - check if all chars present in order
                        else if (this._fuzzyMatch(trimmedQuery, strValue)) {
                            results.push({
                                tableId, tableTitle, colId,
                                colLabel: colDef ? colDef.label : colId,
                                value: String(value), rowId: row.id,
                                score: 25, type: 'fuzzy'
                            });
                        }
                    });
                });
            });
        });

        // Sort by score (highest first) and deduplicate
        const unique = new Map();
        results.sort((a, b) => b.score - a.score);
        results.forEach(r => {
            const key = `${r.tableId}:${r.rowId}`;
            if (!unique.has(key)) unique.set(key, r);
        });

        this.currentResults = Array.from(unique.values()).slice(0, 10);
        this.selectedIndex = this.currentResults.length > 0 ? 0 : -1;
        this._renderSearchResults(this.currentResults, trimmedQuery);
    }

    _fuzzyMatch(needle, haystack) {
        let idx = 0;
        for (let i = 0; i < haystack.length && idx < needle.length; i++) {
            if (haystack[i] === needle[idx]) idx++;
        }
        return idx === needle.length;
    }

    _renderSearchResults(results, query) {
        const resultsDropdown = this.element.querySelector('.search-results-dropdown');
        if (!resultsDropdown) return;

        if (results.length === 0) {
            resultsDropdown.innerHTML = '<div class="no-results" style="padding:12px; color:var(--text-muted);">Keine Ergebnisse gefunden</div>';
        } else {
            resultsDropdown.innerHTML = results.map((res, i) => {
                return `
                    <div class="search-result-item ${i === this.selectedIndex ? 'selected' : ''}" 
                         data-index="${i}"
                         data-table-id="${res.tableId}" 
                         data-row-id="${res.rowId}" 
                         data-col-id="${res.colId}">
                        <div class="result-meta">
                            <span class="result-table-name">${res.tableTitle}</span>
                            <span class="result-col-name">${res.colLabel}</span>
                        </div>
                        <div class="result-content">
                            ${this._highlightSearchTerm(res.value, query)}
                        </div>
                    </div>
                `;
            }).join('');
        }

        resultsDropdown.classList.add('show');
    }

    _updateSelectedResultUI() {
        const resultsDropdown = this.element.querySelector('.search-results-dropdown');
        if (!resultsDropdown) return;

        resultsDropdown.querySelectorAll('.search-result-item').forEach((item, i) => {
            item.classList.toggle('selected', i === this.selectedIndex);
        });
    }

    _highlightSearchTerm(text, query) {
        if (!query) return text;
        const regex = new RegExp(`(${query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi');
        return text.replace(regex, '<span class="search-highlight">$1</span>');
    }

    _closeAllDropdowns() {
        this.element.querySelectorAll('.dropdown-container').forEach(c => c.classList.remove('show'));
    }

    switchTo(table) {
        this.currentTable = table;
        this.element.querySelectorAll('.nav-btn:not(.persons-toggle-btn):not(.inventory-toggle-btn):not(.calendar-toggle-btn)').forEach(btn => {
            btn.classList.toggle('active', btn.dataset.table === table);
        });
    }

    showUnsavedBanner() {
        const banner = this.element.querySelector('.unsaved-banner');
        if (banner) {
            banner.style.display = 'flex';
            this.setLoading(false); // Reset loading state when showing banner
        }
    }

    hideUnsavedBanner() {
        const banner = this.element.querySelector('.unsaved-banner');
        if (banner) {
            banner.style.display = 'none';
            this.setLoading(false);
        }
    }

    setLoading(isLoading) {
        const banner = this.element.querySelector('.unsaved-banner');
        if (!banner) return;
        const msg = banner.querySelector('.unsaved-msg');
        const saveBtn = banner.querySelector('.save-btn-header');
        const discardBtn = banner.querySelector('.discard-btn-header');
        const bar = banner.querySelector('.save-loading-bar');

        if (isLoading) {
            document.body.classList.add('global-loading');
            if (msg) msg.textContent = 'Speichere...';
            if (saveBtn) {
                saveBtn.disabled = true;
                saveBtn.textContent = 'Speichern...';
            }
            if (discardBtn) discardBtn.disabled = true;
            if (bar) bar.style.display = 'block';
        } else {
            document.body.classList.remove('global-loading');
            if (msg) msg.textContent = 'Ungespeicherte Änderungen vorhanden';
            if (saveBtn) {
                saveBtn.disabled = false;
                saveBtn.textContent = 'Speichern';
            }
            if (discardBtn) discardBtn.disabled = false;
            if (bar) bar.style.display = 'none';
        }
    }

    showFlash(message, type = 'success') {
        const banner = this.element.querySelector('.flash-banner');
        if (!banner) return;

        banner.textContent = message;
        banner.className = `flash-banner flash-${type}`;
        banner.style.display = 'block';
        banner.style.opacity = '1';

        setTimeout(() => {
            banner.style.opacity = '0';
            setTimeout(() => {
                banner.style.display = 'none';
            }, 300);
        }, 3000);
    }
}
